/* telc B1 Sprachbausteine: the Teil 2 word list and the Teil 1 patterns, built from the exam data by sb_vocab.py (build_ref_pages.py) */
window.TELC_SBW = {"t2":[{"w":"aber","key":"ABER","ty":"connector","en":"but","note":"Connector, main clause: the verb stays in position 2 (Ich komme, aber ich habe wenig Zeit). Contrast.","ans":3,"inList":3,"ex":[{"x":"Nadja","no":4,"n":35,"de":"Ich kann zwar schon ganz gut schreiben, 【aber】 ich habe immer wieder Probleme beim freien Sprechen.","en":"I can already write quite well, 【but】 I keep having problems with free speaking.","rule":"Zwar … ABER: the pair marks a contrast (writing is good, but speaking is difficult). Aber stands in position 0 and does not change the word order of the following main clause."},{"x":"Nicole","no":5,"n":34,"de":"Mein Sohn Matthias macht in zwei Jahren sein Abitur, 【aber】 seine Leistungen sind zurzeit nicht so gut.","en":"My son Matthias takes his school-leaving exam in two years, 【but】 his results are not so good at the moment.","rule":"Mein Sohn macht in zwei Jahren Abitur, ABER seine Leistungen sind nicht gut: aber links two main clauses and stands in position 0 (no word-order change)."},{"x":"Vera","no":11,"n":36,"de":"Wir fahren zwar beide auch Ski, 【aber】 der Winter den Bergen ist nicht so unbedingt unsere Sache.","en":"We both ski too, 【but】 winter in the mountains is not really our thing.","rule":"Wir fahren ZWAR beide Ski, ABER … = contrast. Aber has position 0 (does not change the word order)."}],"own":null},{"w":"als","key":"ALS","ty":"connector","en":"when (once in the past), as, than","note":"Past, one single event (Als ich jung war …); also comparison after a comparative (größer als).","ans":1,"inList":3,"ex":[{"x":"Sonja","no":9,"n":33,"de":"【Als】 ich eine Zeitschrift durchsah, ist mir Ihre Anzeige aufgefallen, und nun habe ich folgende Fragen an Sie: Von welchen Nahrungsmitteln darf man eigentlich so viel essen, wie man will?","en":"【When】 I was looking through a magazine, your advertisement caught my eye, and now I have the following questions for you: of which foods may one actually eat as much as one wants?","rule":"ALS = when, one single event in the past: Als ich eine Zeitschrift durchsah, … (Präteritum). The verb of the als-clause stands at the end."}],"own":null},{"w":"am","key":"AM","ty":"preposition","en":"on the, at the","note":"an + dem: with days, parts of the day, weekend (am Montag, am Abend) and with superlatives (am liebsten).","ans":2,"inList":2,"ex":[{"x":"Petra","no":1,"n":36,"de":"Ich arbeite 【am】 liebsten mit meinem PC.","en":"I like working on my PC 【most of all】.","rule":"Am liebsten = best of all. The superlative of gern is gern – lieber – am liebsten: ich arbeite am liebsten mit dem PC = I like working on the PC most."},{"x":"Jennifer","no":12,"n":38,"de":"Wir suchen ein Hotel, möglichst 【am】 Ufer des Rheins.","en":"We are looking for a hotel, if possible 【on the】 bank of the Rhine.","rule":"AM + superlative of a place: am ruhigsten Ende = at the quietest end. The book's text is incomplete after the gap: it should read 'am ruhigen Ende gelegen sein'."}],"own":null},{"w":"anfangen","key":"ANFANGEN","ty":"verb","en":"to begin","note":"Separable verb: ich fange an. Often \"mit + Dativ\" (mit dem Kurs anfangen).","ans":0,"inList":2,"ex":[],"own":["Wir wollen morgen mit dem Kurs anfangen.","We want to start the course tomorrow."]},{"w":"Anfrage","key":"ANFRAGE","ty":"noun","en":"enquiry, request","note":"Noun, die Anfrage: an enquiry. Common in formal letters (auf Ihre Anfrage).","ans":0,"inList":1,"ex":[],"own":["Ich schreibe Ihnen wegen meiner Anfrage vom Montag.","I am writing to you about my enquiry of Monday."]},{"w":"Angebot","key":"ANGEBOT","ty":"noun","en":"offer","note":"Noun, das Angebot: an offer (a special offer, a quote). Plural: die Angebote.","ans":1,"inList":1,"ex":[{"x":"Annika","no":7,"n":40,"de":"Ich freue mich auf Ihr 【Angebot】.","en":"I look forward to your 【offer】.","rule":"Sich freuen auf + Akkusativ: auf IHR ANGEBOT. Ihr = Akkusativ neuter (das Angebot)."}],"own":null},{"w":"antworten","key":"ANTWORTEN","ty":"noun or verb","en":"answers; to answer","note":"Verb: antworten + Dativ (Ich antworte Ihnen). Noun: die Antworten (answers).","ans":0,"inList":1,"ex":[],"own":["Bitte antworten Sie bis Freitag.","Please answer by Friday."]},{"w":"arbeiten","key":"ARBEITEN","ty":"verb","en":"to work","note":"Verb: arbeiten als (Beruf), arbeiten bei (Firma), arbeiten an + Dativ.","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":35,"de":"Mein Chef machte mir damals das Angebot, acht Monate im Tochterunternehmen der Firma in Portugal zu 【arbeiten】, was ich dann auch getan habe.","en":"My boss then offered me to 【work】 for eight months in the company's subsidiary in Portugal, which I then did.","rule":"Zu-infinitive after anbieten: mir ein Angebot, … zu ARBEITEN. After zu the infinitive of the verb is needed (zu arbeiten). Gearbeitet would be a participle."}],"own":null},{"w":"auch","key":"AUCH","ty":"particle","en":"also, too","note":"Also, too. Stands next to the word it stresses (Ich komme auch).","ans":2,"inList":2,"ex":[{"x":"Sophie","no":3,"n":32,"de":"Ich interessiere mich sowohl für das Seminar Schutz gegen Computerviren als 【auch】 für Einführung ins Internet.","en":"I am interested both in the seminar Protection against Computer Viruses and 【also】 in Introduction to the Internet.","rule":"Two-part conjunction: sowohl … als auch (both … and). Only AUCH completes the pair."},{"x":"Thomas","no":14,"n":38,"de":"Es sollte 【auch】 ruhig gelegen sein.","en":"It should 【also】 be quiet.","rule":"Es sollte AUCH ruhig gelegen sein = also: auch adds a second requirement of the hotel (quiet location)."}],"own":null},{"w":"auf","key":"AUF","ty":"preposition","en":"on, onto","note":"Preposition. Fixed pairs: warten auf, sich freuen auf, achten auf, aufmerksam auf (+ Akkusativ).","ans":3,"inList":4,"ex":[{"x":"Sonja","no":9,"n":38,"de":"Für eine Antwort 【auf】 meine Fragen danke ich Ihnen im Voraus.","en":"For an answer 【to】 my questions I thank you in advance.","rule":"Antwort AUF + Akkusativ: fixed pair (die Antwort auf meine Frage). Für / von would change the meaning."},{"x":"Viktor","no":17,"n":40,"de":"Für Ihre Antwort 【auf】 meine Fragen bedanke ich mich vielmals.","en":"For your answer 【to】 my questions I thank you very much.","rule":"Antwort AUF + Akkusativ: Für Ihre Antwort auf meine Fragen bedanke ich mich. Fixed pair die Antwort auf."}],"own":null},{"w":"Auftrag","key":"AUFTRAG","ty":"noun","en":"order, task","note":"Noun, der Auftrag: an order or a task given by a customer or a boss.","ans":2,"inList":2,"ex":[{"x":"Jennifer","no":12,"n":31,"de":"Unsere Organisation hat den 【Auftrag】, eine deutsch-französische Konferenz zu europäischen Entwicklungsprogrammen vorzubereiten.","en":"Our organisation has the 【task】 of preparing a German-French conference on European development programmes.","rule":"Den AUFTRAG haben, … zu = to have the task of: Haben + Akkusativ (der Auftrag, masculine: den). Followed by a zu-infinitive (… eine Konferenz vorzubereiten)."}],"own":null},{"w":"außen","key":"AUSSEN","ty":"adverb","en":"outside","note":"Adverb (written außen): on the outside. The opposite is innen.","ans":0,"inList":1,"ex":[],"own":["Außen ist das Haus rot, innen ist es weiß.","On the outside the house is red, inside it is white."]},{"w":"außerdem","key":"AUSSERDEM","ty":"adverb","en":"besides, in addition","note":"Adverb (written außerdem): adds a point. It takes position 1, the verb follows (Außerdem habe ich …).","ans":1,"inList":1,"ex":[{"x":"Eva","no":2,"n":38,"de":"【Außerdem】 möchte ich wissen, ob man in der Gegend um das Hotel einfache Wanderungen unternehmen kann.","en":"【Besides,】 I would like to know whether you can go on easy walks in the area around the hotel.","rule":"Außerdem = besides, in addition. It starts the sentence; in the main clause the verb stays in second place (Außerdem möchte ich …). It adds a further point to the list of questions."}],"own":null},{"w":"bei","key":"BEI","ty":"preposition","en":"at, with, near","note":"Preposition + Dativ: at a person or company (bei meiner Firma), near, at the same time as (bei der Arbeit).","ans":1,"inList":1,"ex":[{"x":"Carolina","no":10,"n":37,"de":"【Bei】 unserem Quantum-System spielen Sie mit einer Chance auf einen Gewinn von 1 Million Euro!","en":"【With】 our Quantum system you play with a chance of a prize of 1 million euros!","rule":"BEI unserem Quantum-System = with our system (the rules of the game). Bei + Dativ. The words after the gap are missing in the exam text."}],"own":null},{"w":"beiden","key":"BEIDEN","ty":"adjective","en":"both","note":"Both. Usually with an article: die beiden Kinder, mit beiden Händen.","ans":1,"inList":1,"ex":[{"x":"Sophie","no":3,"n":36,"de":"Gibt es für die 【beiden】 Seminare noch genügend freie Plätze?","en":"Are there still enough free places for the 【two】 seminars?","rule":"Die beiden Seminare = both seminars. After the article die (plural) the adjective-like word beide takes -n: beiden."}],"own":null},{"w":"beim","key":"BEIM","ty":"preposition","en":"at the, while (doing)","note":"bei + dem: beim Essen = while eating, beim Arzt = at the doctor's.","ans":1,"inList":1,"ex":[{"x":"Tamara","no":15,"n":33,"de":"【Beim】 Durchsehen einer Zeitschrift ist mir Ihre Anzeige aufgefallen, und nun habe ich folgende Fragen an Sie: Von welchen Nahrungsmitteln darf man eigentlich so viel essen, wie man will?","en":"【While】 looking through a magazine your advertisement caught my eye, and now I have the following questions for you: of which foods may one actually eat as much as one wants?","rule":"BEIM Durchsehen einer Zeitschrift = while looking through a magazine: beim = bei dem + noun-use of an infinitive (das Durchsehen), meaning 'while'."}],"own":null},{"w":"bequem","key":"BEQUEM","ty":"adjective","en":"comfortable","note":"Adjective: comfortable, convenient (ein bequemer Stuhl).","ans":0,"inList":1,"ex":[],"own":["Das Sofa ist sehr bequem.","The sofa is very comfortable."]},{"w":"bereits","key":"BEREITS","ty":"adverb","en":"already","note":"Adverb: already (more formal than schon).","ans":1,"inList":1,"ex":[{"x":"Carolina","no":10,"n":39,"de":"Spielen Sie mit uns das Quantum – System: 【bereits】 700 Quantum – Systemspielgruppen haben zusammen schon über sieben Millionen Euro gewonnen.","en":"Play the Quantum system with us: 【already】 700 Quantum system playing groups have together won over seven million euros.","rule":"BEREITS = already. Bereits 700 Gruppen haben zusammen gewonnen: it stresses that many groups have already won. The meaning decides."}],"own":null},{"w":"beschreiben","key":"BESCHREIBEN","ty":"verb","en":"to describe","note":"Verb: to describe (ich beschreibe, Partizip beschrieben). Note: beschreiben takes an Akkusativ object.","ans":1,"inList":1,"ex":[{"x":"Thomas","no":14,"n":34,"de":"In Ihrer Anzeige 【beschreiben】 Sie die Sehenswürdigkeiten von Breisach und die verschiedenen touristischen Möglichkeiten.","en":"In your advertisement you 【name】 the sights of Breisach and the various tourist options.","rule":"Sie BESCHREIBEN die Sehenswürdigkeiten = you describe: plural verb for the formal Sie. In this version of the text the verb is beschreiben."}],"own":null},{"w":"bis","key":"BIS","ty":"preposition","en":"until, by","note":"Until, by. Bis + time (bis Freitag, bis spät abends, bis zu + Dativ).","ans":1,"inList":1,"ex":[{"x":"Petra","no":1,"n":38,"de":"Wie lange wird es dauern, 【bis】 ich mich meinen Geschäftsfreunden richtig unterhalten kann?","en":"How long will it take 【until】 I can talk properly with my business friends?","rule":"Wie lange wird es dauern, BIS … = until. Bis is also a conjunction: bis ich mich unterhalten kann, the verb (kann) at the end. The time limit of a process (how long until)."}],"own":null},{"w":"dabei","key":"DABEI","ty":"da-word","en":"with it, at the same time","note":"da-word: with it / in doing so; also \"at the same time\". Replaces bei + something.","ans":1,"inList":1,"ex":[{"x":"Annika","no":7,"n":39,"de":"Ich möchte auch wissen, wie die Reisegruppen zusammengesetzt sind, welche Sprache die Reiseleiterin/ der Reiseleiter spricht und ob ein Arzt 【dabei】 ist.","en":"I would like to know too how the travel groups are put together, which language the tour guide speaks and whether a doctor is 【with them】.","rule":"DABEI sein = to be with us (on the tour): ob ein Arzt DABEI ist. Fixed expression dabei sein."}],"own":null},{"w":"dafür","key":"DAFÜR","ty":"da-word","en":"for it, in return","note":"da-word (für + it): for it; also \"in return, on the other hand\" (Das ist teuer, dafür gut).","ans":0,"inList":2,"ex":[],"own":["Das Hotel ist teuer, dafür ist das Frühstück ausgezeichnet.","The hotel is expensive, but in return the breakfast is excellent."]},{"w":"damit","key":"DAMIT","ty":"connector","en":"so that, with it","note":"As a connector: so that (aim), the verb goes to the end. As a da-word: with it.","ans":1,"inList":1,"ex":[{"x":"Nadja","no":4,"n":37,"de":"Am liebsten wäre mir ein vierwöchiger Deutschkurs, der nur vormittags stattfindet, 【damit】 ich nachmittags etwas anderes machen kann.","en":"I would most like a four-week German course that takes place only in the mornings, 【so that】 I can do something else in the afternoons.","rule":"DAMIT = so that, it gives the aim: …, damit ich nachmittags etwas anderes machen kann. Damit opens a subordinate clause, the verb (kann) at the end."}],"own":null},{"w":"danach","key":"DANACH","ty":"adverb","en":"afterwards","note":"Adverb: afterwards. The verb follows in position 2 (Danach gehen wir …).","ans":1,"inList":1,"ex":[{"x":"Annika","no":7,"n":33,"de":"Unsere Vorstellungen sind im Einzelnen diese: Zuerst eine Wanderreise, etwa 10 Tage, möglichst leichte Tageswanderungen(ca. 4 – 5 Stunden), und 【danach】 ein Erholungsurlaub am Meer.","en":"Our ideas in detail are these: First a hiking trip, about 10 days, if possible easy day walks (about 4 to 5 hours), and 【afterwards】 a relaxing holiday by the sea.","rule":"DANACH = afterwards. Sequence: first the hiking trip, then (danach) a relaxing holiday."}],"own":null},{"w":"darf","key":"DARF","ty":"modal verb","en":"may, is allowed to","note":"Modal verb, ich/er/sie: may, am allowed to (Darf ich Sie etwas fragen?). The second verb is an infinitive at the end.","ans":0,"inList":1,"ex":[],"own":["Darf ich Sie etwas fragen?","May I ask you something?"]},{"w":"darin","key":"DARIN","ty":"da-word","en":"in it","note":"da-word (in + it): in it, in that. For things, not people.","ans":1,"inList":1,"ex":[{"x":"Annika","no":7,"n":31,"de":"Nun ist mir beim Lesen der Zeitschrift Berge die Anzeige von Geo-Tours aufgefallen, denn 【darin】 steht, dass Sie auf Erlebnisreisen in Wüstenregionen spezialisiert sind.","en":"Now, while reading the magazine Berge, I noticed the Geo-Tours advertisement, because it says 【in it】 that you specialise in adventure trips to desert regions.","rule":"DARIN refers back to the advertisement: denn DARIN steht, dass … = because in it it says. Darin = in dieser Anzeige."}],"own":null},{"w":"darüber","key":"DARÜBER","ty":"da-word","en":"about it","note":"da-word (über + it): about it. Used with verbs that take \"über\" (sich freuen über, sprechen über).","ans":1,"inList":1,"ex":[{"x":"Viktor","no":17,"n":31,"de":"Mein Deutschlehrer hat mich 【darüber】 informiert, dass Sie in St. Andreasburg Intensivkurse in Deutsch anbieten.","en":"My German teacher 【told me about it】: you offer intensive German courses in St Andreasberg.","rule":"Informieren ÜBER + Akkusativ: mein Lehrer hat mich DARÜBER informiert, dass … Darüber (da + r + über) points forward to the dass-clause."}],"own":null},{"w":"dass","key":"DASS","ty":"connector","en":"that (conjunction)","note":"Connector: that. The verb goes to the end (Ich glaube, dass er kommt).","ans":2,"inList":3,"ex":[{"x":"Petra","no":1,"n":37,"de":"Sie schreiben, 【dass】 Ihr Programm besonders die alltägliche Kommunikation fördert.","en":"You write 【that】 your programme especially promotes everyday communication.","rule":"Sie schreiben, DASS … reports what the advertisement says. Dass opens a subordinate clause: the verb (fördert) goes to the end of the clause."},{"x":"Iris","no":8,"n":31,"de":"Wir möchten Sie darüber informieren, 【dass】 Ihre Versicherungen künftig von Herrn Max Kuhne bearbeitet werden.","en":"We would like to inform you 【that】 your insurance will in future be handled by Mr Max Kuhne.","rule":"Darüber informieren, DASS …: the content of the information is a dass-clause. Dass opens a subordinate clause, so the verb group goes to the end: bearbeitet werden. Ob would be a yes/no question, which is not meant here."}],"own":null},{"w":"der","key":"DER","ty":"article","en":"the (masc. Nominativ / fem. Dativ)","note":"Article: masculine Nominativ (der Mann), also feminine Dativ (mit der Frau) and Genitiv.","ans":2,"inList":2,"ex":[{"x":"Nadja","no":4,"n":36,"de":"Am liebsten wäre mir ein vierwöchiger Deutschkurs, 【der】 nur vormittags stattfindet, damit ich nachmittags etwas anderes machen kann.","en":"I would most like a four-week German course 【that】 takes place only in the mornings, so that I can do something else in the afternoons.","rule":"Relative pronoun for the masculine noun Kurs, subject of 'stattfindet': Nominativ masculine = der. The verb of the relative clause (stattfindet) stands at the end."},{"x":"Rita","no":18,"n":38,"de":"Außerdem würde ich gerne wissen, ob die Haltung von Haustieren in 【der】 Wohnung erlaubt ist.","en":"I would also like to know whether keeping pets is allowed in 【the】 flat.","rule":"Article or relative pronoun. Gender, number and case must fit the noun it belongs to; a relative pronoun takes its gender and number from the noun before it and its case from its own verb or preposition."}],"own":null},{"w":"deshalb","key":"DESHALB","ty":"adverb","en":"therefore, that is why","note":"Adverb: that is why. Position 1, then the verb (Deshalb komme ich nicht).","ans":1,"inList":2,"ex":[{"x":"Nicole","no":5,"n":32,"de":"【Deshalb】 schreibe ich Ihnen diese Mail.","en":"【That is why】 I am writing you this e-mail.","rule":"DESHALB = that is why (result of the busy phone line). After deshalb the verb comes straight after it: Deshalb schreibe ich. A conjunction like weil / dass would send the verb to the end."}],"own":null},{"w":"deswegen","key":"DESWEGEN","ty":"adverb","en":"that is why","note":"Adverb: that is why. Same use as deshalb.","ans":0,"inList":2,"ex":[],"own":["Es regnet, deswegen bleiben wir zu Hause.","It is raining, that is why we stay at home."]},{"w":"die","key":"DIE","ty":"article","en":"the (fem. / plural)","note":"Article or relative pronoun: feminine and plural Nominativ/Akkusativ (die Frau, die Kinder; die Parkplätze, die …).","ans":1,"inList":1,"ex":[{"x":"Rita","no":18,"n":33,"de":"Deshalb suche ich für den 1. November eine Wohnung, 【die】 möglichst zentral gelegen sein sollte.","en":"That is why I am looking for a flat for 1 November 【that】 should be as central as possible.","rule":"Article or relative pronoun. Gender, number and case must fit the noun it belongs to; a relative pronoun takes its gender and number from the noun before it and its case from its own verb or preposition."}],"own":null},{"w":"diese","key":"DIESE","ty":"pronoun","en":"this, these","note":"Pronoun/article: this, these (diese Probleme, diese Frau).","ans":1,"inList":1,"ex":[{"x":"Nicole","no":5,"n":36,"de":"Matthias ist nicht dumm, aber er ist etwas faul und denkt, er brauche 【diese】 Fächer nicht.","en":"Matthias is not stupid, but he is a bit lazy and thinks he does not need 【these】 subjects.","rule":"Brauchen takes the Akkusativ: er braucht DIESE Fächer nicht. Fächer is a plural noun: diese."}],"own":null},{"w":"dort","key":"DORT","ty":"adverb","en":"there","note":"Adverb: there (a place). Not the same as dorthin (movement to there).","ans":1,"inList":1,"ex":[{"x":"Iris","no":8,"n":38,"de":"Leider ist 【dort】 die Adresse von Herrn Kuhne nicht korrekt.","en":"Unfortunately 【there】 the address of Mr Kuhne is not correct.","rule":"Leider ist DORT die Adresse nicht korrekt = unfortunately the address is not correct there (on the invoice). Dort is an adverb of place, no ending. The meaning decides."}],"own":null},{"w":"dürfen","key":"DÜRFEN","ty":"modal verb","en":"may, to be allowed to (wir, sie)","note":"Modal verb, wir/sie: may, be allowed to. Infinitive at the end (Wir dürfen hier nicht parken).","ans":0,"inList":1,"ex":[],"own":["Hier dürfen wir nicht parken.","We are not allowed to park here."]},{"w":"eine","key":"EINE","ty":"article","en":"a, an (fem.)","note":"Indefinite article: feminine Nominativ/Akkusativ (eine Frau, eine Wohnung).","ans":0,"inList":1,"ex":[],"own":["Ich suche eine Wohnung in der Stadt.","I am looking for a flat in the city."]},{"w":"einige","key":"EINIGE","ty":"quantity word","en":"some, several","note":"Quantity word: some, several (einige Tage, einige Fragen). Plural.","ans":1,"inList":1,"ex":[{"x":"Sophie","no":3,"n":33,"de":"Dazu habe ich noch 【einige】 Fragen: Ist die Veranstaltung Einführung ins Internet auch wirklich für Anfänger gedacht?","en":"I still have 【a few】 questions about this: is the event Introduction to the Internet really meant for beginners?","rule":"Einige Fragen = some questions. Einige is followed by a plural noun without article and ends in -e (Akkusativ plural)."}],"own":null},{"w":"einmal","key":"EINMAL","ty":"adverb","en":"once, (just) one time","note":"Adverb: once, one time; \"noch einmal\" = once more, \"auf einmal\" = suddenly.","ans":2,"inList":2,"ex":[{"x":"Carolina","no":10,"n":31,"de":"Wer möchte nicht auch 【einmal】 bei sechs Richtigen im Lotto dabei sein?","en":"Who would not like to be 【there at least once】 with six right numbers in the lottery?","rule":"Wer möchte nicht auch EINMAL … dabei sein? Einmal = once. It softens the wish: to be there at least once."},{"x":"Vera","no":11,"n":40,"de":"Rufen Sie uns doch einfach 【einmal】 an: Tel.: 09243/7448.","en":"Just call us 【once】: Tel.: 09243/7448.","rule":"Rufen Sie uns doch einfach EINMAL an = just call us. Einmal softens the request (like mal). The prefix an goes to the end."}],"own":null},{"w":"entdeckt","key":"ENTDECKT","ty":"verb (Partizip II)","en":"discovered","note":"Partizip II of entdecken (to discover): hat entdeckt.","ans":1,"inList":1,"ex":[{"x":"Vera","no":11,"n":31,"de":"Mein Mann und ich haben Ihre Anzeige im Mitteilungsblatt des Deutschen Alpenvereins 【entdeckt】.","en":"My husband and I 【discovered】 your advertisement in the bulletin of the German Alpine Club.","rule":"ENTDECKT: we have discovered your advertisement. The Perfekt wir haben … entdeckt; the participle is last."}],"own":null},{"w":"erst","key":"ERST","ty":"particle","en":"only, not until, first","note":"Particle: only, not until, first. Stresses that something is later or less than expected (erst um zehn).","ans":0,"inList":1,"ex":[],"own":["Der Zug fährt erst um zehn Uhr.","The train does not leave until ten o'clock."]},{"w":"erstens","key":"ERSTENS","ty":"adverb","en":"firstly","note":"Adverb: firstly. Followed by zweitens, drittens to order points.","ans":0,"inList":1,"ex":[],"own":["Erstens habe ich keine Zeit, und zweitens ist es zu teuer.","Firstly I have no time, and secondly it is too expensive."]},{"w":"erzählt","key":"ERZÄHLT","ty":"verb (Partizip II)","en":"told, tells","note":"Partizip II of erzählen (to tell): hat erzählt. Present tense: er erzählt.","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":38,"de":"Aber dann habe ich nette Kollegen kennen gelernt, die mir auch über die Kultur und das Leben in Portugal 【erzählt】 haben.","en":"But then I got to know nice colleagues who 【told】 me about the culture and life in Portugal too.","rule":"Perfekt in the relative clause: Kollegen, die mir … ERZÄHLT haben. The participle erzählt is last before haben at the end. Die refers to the plural Kollegen."}],"own":null},{"w":"etwas","key":"ETWAS","ty":"pronoun","en":"something","note":"Pronoun: something, a little (etwas Neues, etwas trinken).","ans":0,"inList":1,"ex":[],"own":["Möchtest du etwas trinken?","Would you like something to drink?"]},{"w":"eure","key":"EURE","ty":"possessive article","en":"your (ihr, plural)","note":"Possessive article, plural of du/ihr: your (eure Eltern, eure Wohnung).","ans":0,"inList":1,"ex":[],"own":["Wir besuchen eure Eltern am Sonntag.","We are visiting your parents on Sunday."]},{"w":"falls","key":"FALLS","ty":"connector","en":"in case, if","note":"Connector: in case, if. The verb goes to the end (falls Sie Zeit haben).","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":40,"de":"【Falls】 Sie noch weitere Fragen an mich haben, können Sie mich gerne anrufen, meine Telefonnummer ist 07612/64788980.","en":"【In case】 you have any further questions for me, you are welcome to call me; my telephone number is 07612/64788980.","rule":"FALLS = in case / if: Falls Sie weitere Fragen haben, können Sie mich anrufen. Falls opens a subordinate clause (verb haben at the end), the main clause starts with the verb (können Sie)."}],"own":null},{"w":"fragen","key":"FRAGEN","ty":"noun or verb","en":"questions; to ask","note":"Verb: to ask (ich frage, wir fragen). Noun: die Fragen (questions).","ans":1,"inList":3,"ex":[{"x":"Iris","no":8,"n":34,"de":"Wenn Sie also 【fragen】 zu Ihren Versicherungen haben, wenden Sie sich in Zukunft bitte an Herrn Kuhne.","en":"So if you have 【questions】 about your insurance, please contact Mr Kuhne in future.","rule":"Wenn Sie FRAGEN haben = if you have questions. Fragen is the plural noun (die Frage), Akkusativ plural, object of haben. It is capitalised in the list as it is a noun."}],"own":null},{"w":"für","key":"FÜR","ty":"preposition","en":"for","note":"Preposition + Akkusativ: for (für mich), also \"for a period\" (für drei Wochen); fixed pairs: danken für, sich interessieren für.","ans":3,"inList":3,"ex":[{"x":"Petra","no":1,"n":32,"de":"Da ich 【für】 einige Monate beruflich nach Südamerika gehe, muss ich sehr schnell Spanisch lernen.","en":"As I am going to South America 【for】 some months on business, I have to learn Spanish very quickly.","rule":"Für + Akkusativ with a length of time: für einige Monate = for some months (how long will I be away)."},{"x":"Eva","no":2,"n":32,"de":"Ich habe Ihre Anzeige in der Zeitung vom letzten Wochenende gelesen und interessiere mich sehr 【für】 das Angebot.","en":"I read your advertisement in the newspaper of last weekend and am very interested 【in】 the offer.","rule":"Sich interessieren FÜR + Akkusativ: fixed verb + preposition pair (ich interessiere mich für das Angebot). Learn the pair, the case follows from the preposition."},{"x":"Iris","no":8,"n":37,"de":"Im Übrigen möchten wir uns 【für】 einen Fehler in unserer letzten Beitragsrechnung entschuldigen.","en":"Incidentally, we would like to apologise 【for】 an error in our last premium invoice.","rule":"Sich entschuldigen FÜR + Akkusativ: wir möchten uns für einen Fehler entschuldigen. Fixed verb + preposition pair, one phrase with the reflexive pronoun uns."}],"own":null},{"w":"ganz","key":"GANZ","ty":"adverb","en":"quite, whole","note":"Adverb: quite, completely (ganz gut); adjective: whole (die ganze Zeit).","ans":1,"inList":1,"ex":[{"x":"Carolina","no":10,"n":36,"de":"Dadurch erhöhen sich 【ganz】 automatisch Ihre Chancen!","en":"This 【completely】 automatically increases your chances!","rule":"Dadurch erhöhen sich GANZ automatisch Ihre Chancen = completely automatically. Ganz strengthens an adjective or adverb."}],"own":null},{"w":"garantieren","key":"GARANTIEREN","ty":"verb","en":"to guarantee","note":"Verb: to guarantee (Wir garantieren Ihnen …). Formal.","ans":1,"inList":1,"ex":[{"x":"Carolina","no":10,"n":38,"de":"Alle Gewinne erhalten Sie umgehend und ungekürzt zu 100%- das 【garantieren】 wir Ihnen!","en":"You receive all prizes immediately and in full, 100 % – we 【guarantee】 you that!","rule":"Das GARANTIEREN wir Ihnen: wir + garantieren (1st person plural). The object das is first, the verb second, subject third (inversion)."}],"own":null},{"w":"geeignet","key":"GEEIGNET","ty":"adjective","en":"suitable","note":"Adjective: suitable. Often with \"für\" (für etwas geeignet) or \"als\".","ans":4,"inList":4,"ex":[{"x":"Andreas","no":6,"n":40,"de":"Ich bin gerne bereit, mich bei Ihnen vorzustellen, damit Sie sehen können, dass ich für die Tätigkeit 【geeignet】 bin.","en":"I am happy to introduce myself to you so that you can see that I am 【suitable】 for the job.","rule":"Ich bin für die Tätigkeit GEEIGNET = suitable. Sein + adjective, the sentence ends with the verb bin (dass-clause)."},{"x":"Thomas","no":14,"n":35,"de":"Deshalb erscheint uns Ihre Stadt als sehr 【geeignet】, auch weil sie als Brücke zu Europa gilt.","en":"Your town therefore seems very 【suitable】 to us, also because of its reputation as a bridge to Europe.","rule":"Als sehr GEEIGNET erscheinen = to seem very suitable. After als and sehr the adjective keeps its basic form (no ending): geeignet."},{"x":"Rita","no":18,"n":35,"de":"Ich hätte jedoch noch einige Fragen zu Ihrer Anzeige: Ist die Wohnung auch für Kleinkinder 【geeignet】?","en":"I do have some questions about your advertisement: is the flat also 【suitable】 for small children?","rule":"The meaning of the sentence decides. Cross out each word of the list after you use it, because every word is used only once."}],"own":null},{"w":"gegenüber","key":"GEGENÜBER","ty":"preposition","en":"opposite","note":"Preposition + Dativ: opposite. Often after the noun (dem Bahnhof gegenüber).","ans":0,"inList":2,"ex":[],"own":["Das Café liegt dem Bahnhof gegenüber.","The café is opposite the station."]},{"w":"gerne","key":"GERNE","ty":"adverb","en":"gladly","note":"Adverb: gladly (also gern). Shows what you like (Ich komme gerne).","ans":1,"inList":1,"ex":[{"x":"Rita","no":18,"n":37,"de":"Außerdem würde ich 【gerne】 wissen, ob die Haltung von Haustieren in der Wohnung erlaubt ist.","en":"I would also 【like to】 know whether keeping pets is allowed in the flat.","rule":"The meaning of the sentence decides. Cross out each word of the list after you use it, because every word is used only once."}],"own":null},{"w":"gestern","key":"GESTERN","ty":"adverb","en":"yesterday","note":"Adverb of time: yesterday. Goes with the past tense or Perfekt.","ans":0,"inList":1,"ex":[],"own":["Gestern war ich im Kino.","Yesterday I was at the cinema."]},{"w":"gute","key":"GUTE","ty":"adjective","en":"good","note":"Adjective with an ending: -e after the article (die gute Idee) or in the plural (gute Freunde).","ans":1,"inList":1,"ex":[],"own":["Wir haben gute Nachrichten für Sie.","We have good news for you."]},{"w":"haben","key":"HABEN","ty":"verb","en":"have","note":"Verb: to have, wir/sie haben. Also the helper of the Perfekt (wir haben gelernt).","ans":0,"inList":1,"ex":[],"own":["Wir haben am Wochenende keine Zeit.","We have no time at the weekend."]},{"w":"hätte","key":"HÄTTE","ty":"verb (Konjunktiv II)","en":"would have","note":"Konjunktiv II of haben: would have. Polite or unreal (Ich hätte gern …, Wenn ich Zeit hätte).","ans":3,"inList":4,"ex":[{"x":"Andreas","no":6,"n":32,"de":"Wenn ich die Möglichkeit 【hätte】, noch ein wenig zu verdienen, würde mir das sehr helfen.","en":"If I 【had】 the chance to earn a little more, it would help me a lot.","rule":"Wenn ich die Möglichkeit HÄTTE: Konjunktiv II of haben, an unreal condition, followed by würde-form in the main clause (würde mir helfen). The verb stands at the end (hätte, the infinitive 'zu verdienen' follows)."},{"x":"Annika","no":7,"n":35,"de":"Zur Wanderreise 【hätte】 ich noch folgende Fragen: Wird das Gepäck von einem Übernachtungsort zum nächsten transportiert?","en":"About the hiking trip I 【would have】 the following questions: is the luggage transported from one overnight place to the next?","rule":"Zur Wanderreise HÄTTE ich noch Fragen: Konjunktiv II of haben as a polite form. Verb in second position after the phrase Zur Wanderreise (inversion)."},{"x":"Viktor","no":17,"n":37,"de":"Bevor ich mich für einen Sprachkurs in St. Andreasburg entscheide, 【hätte】 ich noch einige Fragen.","en":"Before I decide on a language course in St Andreasberg, I 【have】 a few more questions.","rule":"Bevor ich mich entscheide, HÄTTE ich noch einige Fragen: Konjunktiv II of haben for a polite statement. After the subordinate clause the main clause starts with the verb (hätte ich)."}],"own":null},{"w":"hatten","key":"HATTEN","ty":"verb","en":"had (wir, sie)","note":"Präteritum of haben, wir/sie: had.","ans":0,"inList":1,"ex":[],"own":["Wir hatten gestern keinen Strom.","We had no electricity yesterday."]},{"w":"hilft","key":"HILFT","ty":"verb","en":"helps","note":"Verb: er/sie hilft = helps. Helfen takes the Dativ (Das hilft mir).","ans":1,"inList":1,"ex":[{"x":"Iris","no":8,"n":36,"de":"Auch im Schadensfall 【hilft】 er Ihnen schnell und zuverlässig weiter.","en":"Also in case of damage 【he helps】 you on quickly and reliably.","rule":"Auch im Schadensfall HILFT er Ihnen weiter: after the phrase at the start the verb is in second position (inversion): hilft er. Weiterhelfen is separable (hilft … weiter) and takes the Dativ (Ihnen)."}],"own":null},{"w":"ihnen","key":"IHNEN","ty":"pronoun","en":"you (formal, Dativ), them (Dativ)","note":"Pronoun, Dativ: (to) them, or (to) you with a capital letter (formal).","ans":2,"inList":2,"ex":[{"x":"Andreas","no":6,"n":39,"de":"Ich bin gerne bereit, mich bei 【Ihnen】 vorzustellen, damit Sie sehen können, dass ich für die Tätigkeit geeignet bin.","en":"I am happy to introduce myself to 【you】 so that you can see that I am suitable for the job.","rule":"Sich vorstellen bei + Dativ: bei IHNEN (formal Dativ of Sie). The preposition bei always takes the Dativ."},{"x":"Iris","no":8,"n":40,"de":"Wir danken 【Ihnen】 für Ihr Vertrauen.","en":"We thank 【you】 for your trust.","rule":"Danken takes the Dativ: wir danken IHNEN für Ihr Vertrauen (formal Dativ of Sie). Sie would be Akkusativ, which danken does not take."}],"own":null},{"w":"ihre","key":"IHRE","ty":"possessive article","en":"your (formal), her, their","note":"Possessive article: your (formal, capital Ihre), her, their (ihre Familie).","ans":1,"inList":1,"ex":[{"x":"Iris","no":8,"n":32,"de":"Ihm wurden 【Ihre】 Unterlagen übergeben.","en":"【Your】 documents have been handed to him.","rule":"Ihm wurden IHRE Unterlagen übergeben: passive with the plural subject Ihre Unterlagen (Nominativ plural, possessive Ihre). The person who receives them is in the Dativ (Ihm). The book prints the noun as 'Unterlangen', a typo."}],"own":null},{"w":"in","key":"IN","ty":"preposition","en":"in","note":"Preposition: in. Place (wo?) + Dativ (in der Stadt), movement (wohin?) + Akkusativ (in die Stadt).","ans":2,"inList":3,"ex":[{"x":"Nadja","no":4,"n":31,"de":"Ich komme aus Kroatien und möchte 【in】 den nächsten Sommerferien mein Deutsch verbessern.","en":"I come from Croatia and would like to improve my German 【in】 the coming summer holidays.","rule":"In + Dativ plural for a time: in den nächsten Sommerferien = in the next summer holidays. The article den ends with -n, so the noun group is Dativ plural."},{"x":"Nicole","no":5,"n":33,"de":"Mein Sohn Matthias macht 【in】 zwei Jahren sein Abitur, aber seine Leistungen sind zurzeit nicht so gut.","en":"My son Matthias takes his school-leaving exam 【in】 two years, but his results are not so good at the moment.","rule":"IN + Dativ for a time in the future: in zwei Jahren = in two years. The time is counted from now."}],"own":null},{"w":"Informationen","key":"INFORMATIONEN","ty":"noun","en":"information","note":"Noun, plural: die Informationen = information (also: die Information).","ans":2,"inList":2,"ex":[{"x":"Jennifer","no":12,"n":33,"de":"Diese Veranstaltung könnte in Breisach stattfinden, und daher brauchen wir von Ihnen nähere 【Informationen】.","en":"This event could take place in Breisach, and we therefore need further 【information】 from you.","rule":"Nähere INFORMATIONEN: plural noun in the Akkusativ plural, the adjective ending is -e (nähere). Information is feminine, the plural is Informationen."}],"own":null},{"w":"informiert","key":"INFORMIERT","ty":"verb (Partizip II)","en":"informed","note":"Partizip II of informieren (to inform): hat informiert; also \"gut informiert\".","ans":1,"inList":3,"ex":[{"x":"Iris","no":8,"n":35,"de":"Er berät und 【informiert】 Sie gern.","en":"He advises and 【informs】 you gladly.","rule":"Er berät und INFORMIERT Sie gern: two verbs with the same subject er, both in the 3rd person singular (berät, informiert). Informieren takes the Akkusativ (Sie)."}],"own":null},{"w":"interessiert","key":"INTERESSIERT","ty":"adjective","en":"interested","note":"Adjective/Partizip: interested. \"sich interessieren für\" and \"interessiert sein an + Dativ\".","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":31,"de":"Ich habe Ihre Anzeige in der Neuen Presse gelesen und bin an dem Filmprojekt sehr 【interessiert】.","en":"I read your advertisement in the Neue Presse and am very 【interested】 in the film project.","rule":"Sich interessieren / interessiert sein AN + Dativ: ich bin an dem Filmprojekt INTERESSIERT. Sein + participle used as an adjective."}],"own":null},{"w":"jeden","key":"JEDEN","ty":"article","en":"every, each (Akkusativ)","note":"Article: every, each, Akkusativ masculine (jeden Tag) or Dativ with plural-type phrases.","ans":1,"inList":1,"ex":[{"x":"Andreas","no":6,"n":35,"de":"Seit über dreißig Jahren treibe ich 【jeden】 Tag Sport.","en":"For over thirty years I have done sport 【every】 day.","rule":"JEDEN Tag = every day. A time expression in the Akkusativ: jeder Tag (masculine) → jeden Tag."}],"own":null},{"w":"kann","key":"KANN","ty":"modal verb","en":"can","note":"Modal verb, ich/er/sie: can (Ich kann kommen). Infinitive at the end.","ans":1,"inList":2,"ex":[{"x":"Nicole","no":5,"n":31,"de":"Leider 【kann】 ich Sie im Moment nicht anrufen, da das Telefon immer belegt ist.","en":"Unfortunately I 【cannot】 phone you at the moment, because the line is always busy.","rule":"After leider the verb stays in second place: Leider KANN ich Sie nicht anrufen (inversion: adverb, verb, subject). Kann = 1st person of können."}],"own":null},{"w":"keine","key":"KEINE","ty":"article","en":"no, none (fem. / plural)","note":"Negative article: feminine and plural (keine Zeit, keine Probleme).","ans":1,"inList":1,"ex":[{"x":"Petra","no":1,"n":33,"de":"Für einen richtigen Sprachkurs habe ich leider 【keine】 Zeit.","en":"Unfortunately I have 【no】 time for a proper language course.","rule":"Keine Zeit: negative article kein- before a noun without article. Zeit is feminine, Akkusativ (haben + Akk) = keine. The word list prints it as KEINE, a typo of the book."}],"own":null},{"w":"keines","key":"KEINES","ty":"article","en":"no, none (neuter)","note":"Negative: neuter (keines der Kinder, Ein Auto? Wir haben keines).","ans":0,"inList":1,"ex":[],"own":["Ein Auto? Wir haben keines.","A car? We do not have one."]},{"w":"kennen","key":"KENNEN","ty":"verb","en":"to know (a person or place)","note":"Verb: to know a person, a place or a thing (Ich kenne ihn).","ans":1,"inList":1,"ex":[{"x":"Vera","no":11,"n":35,"de":"Und wenn es unser Terminkalender erlaubt, gehen wir auch noch am Wochenende wandern, oft fahren wir in die Gegend vom Wilden Kaiser, wo wir inzwischen alle Wanderwege 【kennen】.","en":"And when our diary allows it, we also go hiking at the weekend, often we drive to the area of the Wilder Kaiser, where we 【know】 all the hiking trails by now.","rule":"Wo wir … alle Wanderwege KENNEN: relative clause with wo, verb at the end, the subject is wir (plural): kennen."}],"own":null},{"w":"können","key":"KÖNNEN","ty":"modal verb","en":"can (wir, sie)","note":"Modal verb, wir/sie: can, are able to. Infinitive at the end.","ans":1,"inList":2,"ex":[{"x":"Carolina","no":10,"n":33,"de":"Vertrauen Sie beim Lottospiel nicht nur auf das Glück, denn Sie 【können】 Ihre Chancen selbst stark verbessern, wenn Sie mit unserem Lotterie-System spielen – und das für nur 5 Euro in der Woche!","en":"When playing the lottery, do not trust only in luck, because you 【can】 greatly improve your chances yourself if you play with our lottery system – and for only 5 euros a week!","rule":"The subject is Sie (plural): Sie KÖNNEN … verbessern. Können + infinitive. The verb könnte = Konjunktiv, kann = singular."}],"own":null},{"w":"könnte","key":"KÖNNTE","ty":"modal verb (Konjunktiv II)","en":"could (ich, er/sie/es)","note":"Konjunktiv II of können, ich/er/sie: could. Polite request (Könnten Sie …?) or possibility.","ans":0,"inList":1,"ex":[],"own":["Könnte ich bitte das Fenster öffnen?","Could I open the window, please?"]},{"w":"könnten","key":"KÖNNTEN","ty":"modal verb (Konjunktiv II)","en":"could (wir, sie)","note":"Konjunktiv II of können, wir/sie: could, polite or possible.","ans":2,"inList":4,"ex":[{"x":"Sophie","no":3,"n":35,"de":"【Könnten】 Sie mir die Schulungsunterlagen bereits vorher schicken?","en":"【Could】 you send me the training documents beforehand?","rule":"Polite request in a question: KÖNNTEN Sie mir … schicken? Konjunktiv II of können, the verb at the start of the yes/no question, the infinitive schicken at the end."},{"x":"Nicole","no":5,"n":39,"de":"Mir wäre es jedenfalls sehr wichtig, dass Sie meinem Sohn helfen 【könnten】.","en":"In any case it would be very important to me that you 【could】 help my son.","rule":"Dass Sie meinem Sohn helfen KÖNNTEN: polite wish in the dass-clause, Konjunktiv II of können (3rd plural / Sie). The verb is last. Helfen takes the Dativ (meinem Sohn)."}],"own":null},{"w":"lernen","key":"LERNEN","ty":"verb","en":"to learn","note":"Verb: to learn, to study. Infinitive after modal verbs (Ich möchte Deutsch lernen).","ans":0,"inList":1,"ex":[],"own":["Ich möchte besser Deutsch lernen.","I would like to learn German better."]},{"w":"machen","key":"MACHEN","ty":"verb","en":"to make, to do","note":"Verb: to make, to do. Very common: Urlaub machen, einen Plan machen.","ans":1,"inList":1,"ex":[{"x":"Carolina","no":10,"n":40,"de":"【Machen】 Sie hier unbedingt mit!","en":"【Take part】 here without fail!","rule":"Imperative with Sie: MACHEN Sie mit! (mitmachen). The verb comes first, then the subject; the prefix mit comes at the end of the sentence."}],"own":null},{"w":"manchmal","key":"MANCHMAL","ty":"adverb","en":"sometimes","note":"Adverb: sometimes.","ans":1,"inList":1,"ex":[{"x":"Nadja","no":4,"n":33,"de":"Da kann ich an den Wochenenden vielleicht auch 【manchmal】 nach Hause fahren.","en":"There I may also 【sometimes】 be able to go home at the weekends.","rule":"Manchmal = sometimes (adverb of frequency): vielleicht auch manchmal nach Hause fahren. The meaning decides."}],"own":null},{"w":"mehr","key":"MEHR","ty":"adverb","en":"more","note":"Adverb: more; \"nicht mehr\" = no longer, \"kein … mehr\" = no … left.","ans":0,"inList":1,"ex":[],"own":["Leider habe ich nicht mehr Zeit.","Unfortunately I have no more time."]},{"w":"mich","key":"MICH","ty":"pronoun","en":"me (Akkusativ)","note":"Pronoun, Akkusativ of ich: me (Er ruft mich an; ich freue mich). Also reflexive.","ans":0,"inList":2,"ex":[],"own":["Kannst du mich morgen anrufen?","Can you call me tomorrow?"]},{"w":"mir","key":"MIR","ty":"pronoun","en":"me (Dativ)","note":"Pronoun, Dativ of ich: (to) me (Das gefällt mir; Er hilft mir).","ans":2,"inList":2,"ex":[{"x":"Petra","no":1,"n":31,"de":"Ich schreibe Ihnen auf die Anzeige, die 【mir】 in der heutigen Bild-Zeitung aufgefallen ist.","en":"I am writing to you about the advertisement that caught 【my】 eye in today's Bild newspaper.","rule":"Relative clause: die Anzeige, die mir aufgefallen ist. Auffallen takes the Dativ (etwas fällt MIR auf): mir = Dativ of ich. Mich would be Akkusativ."},{"x":"Nicole","no":5,"n":35,"de":"Ich mache 【mir】 vor allem bei den Fächern Physik und Mathematik große Sorgen.","en":"Above all in the subjects physics and maths I 【worry】 a lot.","rule":"Sich (Dativ) Sorgen machen: ich mache MIR Sorgen. The reflexive Dativ pronoun of ich is mir. Mich would be Akkusativ, which is not used here."}],"own":null},{"w":"mit","key":"MIT","ty":"preposition","en":"with","note":"Preposition + Dativ: with (mit dem Bus, mit meinen Freunden).","ans":1,"inList":3,"ex":[{"x":"Petra","no":1,"n":34,"de":"Aber Ihre Methode interessiert mich, vor allem die Sprachübungen 【mit】 den CDs.","en":"But your method interests me, above all the language exercises 【with】 the CDs.","rule":"Mit + Dativ: mit den CDs (Dativ plural: den + noun; the CDs here are the 'with what?' of the exercises). Mit always takes the Dativ."}],"own":null},{"w":"möchte","key":"MÖCHTE","ty":"modal verb","en":"would like (ich, er/sie/es)","note":"Modal verb, ich/er/sie: would like (Ich möchte einen Kaffee). Polite and very common.","ans":5,"inList":7,"ex":[{"x":"Petra","no":1,"n":40,"de":"Ich 【möchte】 gerne ausprobieren, wie Ihre Methode funktioniert.","en":"I 【would like】 to try out how your method works.","rule":"The sentence is 'Ich möchte gerne ausprobieren': 1st person singular of möchten with ich, plus a second verb in the infinitive (ausprobieren) at the end. Würden / wäre do not fit: no infinitive at the end."},{"x":"Sophie","no":3,"n":38,"de":"Und nun noch eine Frage zur Bezahlung: Auslandsüberweisungen sind sehr teuer, daher 【möchte】 ich wissen, ob man im Voraus bezahlen muss oder auch vor Ort bar bezahlen kann.","en":"And now one more question about payment: transfers abroad are very expensive, so I 【would like to】 know whether one has to pay in advance or can also pay cash on the spot.","rule":"Daher möchte ich wissen: after the adverb daher the conjugated verb comes directly (main clause, verb second): möchte, then ich."},{"x":"Viktor","no":17,"n":36,"de":"Die Oberpfalz 【möchte】 ich schon seit langem einmal kennen lernen.","en":"I have 【wanted】 to get to know the Upper Palatinate for a long time.","rule":"Die Oberpfalz MÖCHTE ich … kennen lernen: the object is first, then the verb möchte, then ich (inversion). Möchte = 1st person singular, infinitive kennen lernen at the end."}],"own":null},{"w":"möchten","key":"MÖCHTEN","ty":"modal verb","en":"would like (wir, sie)","note":"Modal verb, wir/sie: would like (Wir möchten bezahlen).","ans":0,"inList":2,"ex":[],"own":["Wir möchten einen Tisch für vier Personen reservieren.","We would like to reserve a table for four people."]},{"w":"möglich","key":"MÖGLICH","ty":"adjective","en":"possible","note":"Adjective: possible (wenn möglich = if possible; so schnell wie möglich).","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":37,"de":"Eigentlich wollte ich so schnell wie 【möglich】 wieder zurück.","en":"I actually wanted to come back as soon as 【possible】.","rule":"So schnell wie MÖGLICH = as fast as possible. Fixed phrase so + adjective + wie möglich."}],"own":null},{"w":"muss","key":"MUSS","ty":"modal verb","en":"must","note":"Modal verb, ich/er/sie: must, have to (Ich muss gehen).","ans":1,"inList":1,"ex":[{"x":"Rita","no":18,"n":31,"de":"Demnächst 【muss】 ich aber aus beruflichen Gründen mit meinem Sohn (3 Jahre) nach Frankfurt umziehen.","en":"Soon I 【have to】 move to Frankfurt with my son (3 years) for professional reasons.","rule":"Verb. The subject and the sentence decide the form: Konjunktiv II (würde, könnte, hätte) makes polite requests and unreal wishes, sollte gives advice, kann / muss / darf are the normal modal verbs."}],"own":null},{"w":"müssen","key":"MÜSSEN","ty":"modal verb","en":"must (wir, sie)","note":"Modal verb, wir/sie: must, have to. Infinitive at the end.","ans":1,"inList":2,"ex":[{"x":"Eva","no":2,"n":35,"de":"Ist die Benutzung des Hallenbads und der Sauna im Preis enthalten oder 【müssen】 wir diese extra bezahlen?","en":"Is the use of the indoor pool and the sauna included in the price, or 【do we have to】 pay for them extra?","rule":"Yes/no question with oder: … oder MÜSSEN wir diese extra bezahlen? The conjugated verb stands first; wir needs müssen (plural), the infinitive bezahlen at the end."}],"own":null},{"w":"nach","key":"NACH","ty":"preposition","en":"after, to","note":"Preposition + Dativ: after (nach dem Essen), to a city/country (nach Berlin).","ans":1,"inList":1,"ex":[{"x":"Rita","no":18,"n":32,"de":"Demnächst muss ich aber aus beruflichen Gründen mit meinem Sohn (3 Jahre) 【nach】 Frankfurt umziehen.","en":"Soon I have to move 【to】 Frankfurt with my son (3 years) for professional reasons.","rule":"Preposition. Prepositions are fixed with verbs, nouns or times (warten auf, sich freuen über, bis / in / an + time). Look at the word before the gap and learn the pair."}],"own":null},{"w":"nämlich","key":"NÄMLICH","ty":"particle","en":"namely, you see","note":"Particle: namely, you see: gives the reason (Er ist nämlich krank). Not at the beginning.","ans":1,"inList":1,"ex":[{"x":"Annika","no":7,"n":32,"de":"Vielleicht haben Sie das richtige Angebot für uns - 【nämlich】 für mich und meine 17-Jährige Tochter.","en":"Perhaps you have the right offer for us – 【namely】 for me and my 17-year-old daughter.","rule":"NÄMLICH = namely, to be precise: ein Angebot für uns – nämlich für mich und meine Tochter. It adds the explanation."}],"own":null},{"w":"nennen","key":"NENNEN","ty":"verb","en":"to name, to call","note":"Verb: to name, to call (Wir nennen es …); infinitive after a modal.","ans":1,"inList":1,"ex":[{"x":"Jennifer","no":12,"n":34,"de":"In Ihrer Anzeige 【nennen】 Sie die Sehenswürdigkeiten von Breisach und die verschiedenen touristischen Möglichkeiten.","en":"In your advertisement you 【name】 the sights of Breisach and the various tourist options.","rule":"In Ihrer Anzeige NENNEN Sie … = the formal Sie takes the plural form of the verb: nennen. Nennt = er / sie / ihr."}],"own":null},{"w":"nennt","key":"NENNT","ty":"verb","en":"names, calls","note":"Verb: er/sie nennt = names, calls (Er nennt es Glück).","ans":0,"inList":2,"ex":[],"own":["Er nennt seinen Hund Max.","He calls his dog Max."]},{"w":"nichts","key":"NICHTS","ty":"pronoun","en":"nothing","note":"Pronoun: nothing (Ich habe nichts gesehen). Often \"nichts Besonderes\".","ans":2,"inList":2,"ex":[{"x":"Eva","no":2,"n":37,"de":"Sie schreiben darüber leider 【nichts】 in Ihrer Anzeige.","en":"Unfortunately you say 【nothing】 about it in your advertisement.","rule":"Sie schreiben leider NICHTS = they write nothing. Nichts is an indefinite pronoun and needs no article or ending."},{"x":"Andreas","no":6,"n":36,"de":"Auch das frühe Aufstehen macht mir gar 【nichts】 aus.","en":"Getting up early does not bother me 【at all】 either.","rule":"Das macht mir gar NICHTS aus = it does not bother me at all. Fixed phrase (jemandem etwas ausmachen) with the Dativ mir."}],"own":null},{"w":"noch","key":"NOCH","ty":"particle","en":"still, yet","note":"Particle: still (noch nicht = not yet; noch ein = one more).","ans":0,"inList":1,"ex":[],"own":["Ich habe noch keine Antwort bekommen.","I have not received an answer yet."]},{"w":"nun","key":"NUN","ty":"adverb","en":"now","note":"Adverb: now (more written style than jetzt).","ans":1,"inList":1,"ex":[{"x":"Jennifer","no":12,"n":37,"de":"【Nun】 haben wir folgende Bitte.","en":"【Now】 we have the following request.","rule":"The verb of this sentence is missing in the book's version of the text (the original has brauchen wir nun …). The key word is NUN = now. Check the sentence in the original exam; here only the meaning (now we need) fits the list."}],"own":null},{"w":"nur","key":"NUR","ty":"particle","en":"only","note":"Particle: only, just (nur ein Mal, nicht nur … sondern auch).","ans":3,"inList":3,"ex":[{"x":"Carolina","no":10,"n":32,"de":"Vertrauen Sie beim Lottospiel nicht 【nur】 auf das Glück, denn Sie können Ihre Chancen selbst stark verbessern, wenn Sie mit unserem Lotterie-System spielen – und das für nur 5 Euro in der Woche!","en":"When playing the lottery, do not trust 【only】 in luck, because you can greatly improve your chances yourself if you play with our lottery system – and for only 5 euros a week!","rule":"Nicht NUR auf das Glück vertrauen = not only. Nicht nur … sondern (auch): nur limits the trust to luck."},{"x":"Andreas 2","no":13,"n":33,"de":"Länger als ein halbes Jahr habe ich 【nur】 einmal im Ausland gelebt, und zwar vor zwei Jahren.","en":"I have lived abroad for longer than half a year 【only】 once, two years ago.","rule":"Länger als ein halbes Jahr habe ich NUR einmal im Ausland gelebt = only once. Nur limits the quantity (einmal)."}],"own":null},{"w":"ob","key":"OB","ty":"connector","en":"whether, if","note":"Connector: whether, if (indirect yes/no question). The verb goes to the end (Ich weiß nicht, ob er kommt).","ans":3,"inList":4,"ex":[{"x":"Eva","no":2,"n":36,"de":"Weiters würde mich noch interessieren, 【ob】 Pensionisten eine Ermäßigung bekommen.","en":"I would also like to know 【whether】 pensioners get a discount.","rule":"Indirect question without a question word: Es würde mich interessieren, OB Pensionisten eine Ermäßigung bekommen = whether. Ob opens a subordinate clause, verb at the end (bekommen)."},{"x":"Sophie","no":3,"n":39,"de":"Und nun noch eine Frage zur Bezahlung: Auslandsüberweisungen sind sehr teuer, daher möchte ich wissen, 【ob】 man im Voraus bezahlen muss oder auch vor Ort bar bezahlen kann.","en":"And now one more question about payment: transfers abroad are very expensive, so I would like to know 【whether】 one has to pay in advance or can also pay cash on the spot.","rule":"Indirect question: ich möchte wissen, OB man im Voraus bezahlen muss = whether. Ob opens a subordinate clause: the verb (muss) goes to the end."},{"x":"Nicole","no":5,"n":37,"de":"Fragen wollte ich nun, 【ob】 es bei Ihnen auch individuelle Physik – und Mathematiknachhilfe gibt.","en":"I wanted to ask 【whether】 you also offer individual tutoring in physics and maths.","rule":"Indirect yes/no question: Fragen wollte ich, OB es individuellen Unterricht gibt. Ob = whether, opens a subordinate clause (verb gibt at the end)."}],"own":null},{"w":"obwohl","key":"OBWOHL","ty":"connector","en":"although","note":"Connector: although. The verb goes to the end (obwohl es regnet).","ans":0,"inList":2,"ex":[],"own":["Ich gehe spazieren, obwohl es regnet.","I go for a walk although it is raining."]},{"w":"oft","key":"OFT","ty":"adverb","en":"often","note":"Adverb: often.","ans":1,"inList":1,"ex":[{"x":"Vera","no":11,"n":34,"de":"Und wenn es unser Terminkalender erlaubt, gehen wir auch noch am Wochenende wandern, 【oft】 fahren wir in die Gegend vom Wilden Kaiser, wo wir inzwischen alle Wanderwege kennen.","en":"And when our diary allows it, we also go hiking at the weekend, 【often】 we drive to the area of the Wilder Kaiser, where we know all the hiking trails by now.","rule":"Wir gehen wandern, OFT fahren wir … = often. Oft in position 1 forces the verb in position 2 (fahren wir). It is an adverb of frequency."}],"own":null},{"w":"öfter","key":"ÖFTER","ty":"adverb","en":"more often","note":"Adverb: more often (Ich möchte öfter Sport machen).","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":32,"de":"Ich war schon 【öfter】 für einige Wochen im Ausland.","en":"I have 【often】 been abroad for a few weeks.","rule":"Ich war schon ÖFTER im Ausland = I have been abroad several times. Öfter = more often (comparative of oft), used here as 'several times'."}],"own":null},{"w":"ohne","key":"OHNE","ty":"preposition","en":"without","note":"Preposition + Akkusativ: without (ohne mich); \"ohne … zu\" + infinitive.","ans":1,"inList":2,"ex":[{"x":"Andreas","no":6,"n":34,"de":"Daher denke ich, dass ich die Arbeit 【ohne】 Probleme machen kann.","en":"I therefore think that I can do the work 【without】 problems.","rule":"OHNE + Akkusativ: ohne Probleme (plural, no article). Fixed use of ohne with a noun."}],"own":null},{"w":"paar","key":"PAAR","ty":"quantity word","en":"pair; ein paar = a few","note":"ein paar = a few (ein paar Tage); das Paar = the couple.","ans":2,"inList":2,"ex":[{"x":"Nadja","no":4,"n":40,"de":"Bitte empfehlen Sie mir auch ein 【paar】 gute Webseiten über Klagenfurt und den Wörthersee.","en":"Please also recommend 【a few】 good websites about Klagenfurt and the Wörthersee.","rule":"Ein PAAR gute Webseiten = a few good websites. Ein paar (= some) is followed by a plural noun; the adjective gute has no article before it and ends in -e."},{"x":"Vera","no":11,"n":39,"de":"Zum Schluss noch ein 【paar】 Worte zu uns selbst.","en":"Finally a 【few】 words about ourselves.","rule":"Ein PAAR Worte = a few words. Ein paar is followed by the plural (Worte)."}],"own":null},{"w":"pro","key":"PRO","ty":"preposition","en":"per","note":"Preposition: per (pro Woche, pro Person), no article.","ans":1,"inList":1,"ex":[{"x":"Petra","no":1,"n":39,"de":"Und wie viele Stunden 【pro】 Woche sollte man mindestens üben?","en":"And how many hours 【per】 week should one practise at least?","rule":"Pro Woche = per week. Pro + Akkusativ, the noun has no article (pro Tag, pro Monat)."}],"own":null},{"w":"richtige","key":"RICHTIGE","ty":"adjective","en":"correct, right","note":"Adjective: correct, right (die richtige Antwort).","ans":1,"inList":1,"ex":[{"x":"Iris","no":8,"n":39,"de":"Seine 【richtige】 Anschrift und Telefonnummer finden Sie auf diesem Brief oben rechts.","en":"His 【correct】 address and telephone number are at the top right of this letter.","rule":"Seine RICHTIGE Anschrift: Anschrift is feminine; after the possessive Seine (Nominativ feminine) the adjective ends in -e: seine richtige Anschrift."}],"own":null},{"w":"sagt","key":"SAGT","ty":"verb","en":"says","note":"Verb: er/sie sagt = says (Er sagt, dass …).","ans":2,"inList":2,"ex":[{"x":"Sonja","no":9,"n":32,"de":"So 【sagt】 man etwa, wer kein Fleisch isst, lebt nicht nur gesünder, sondern fühlt sich auch besser.","en":"So it 【is said】, for example, that anyone who does not eat meat lives not only healthier but also feels better.","rule":"So SAGT man = so it is said. Man + 3rd person singular. Sagt introduces the claim (that ...); the following clause is the content."}],"own":null},{"w":"schnelle","key":"SCHNELLE","ty":"adjective","en":"fast, quick","note":"Adjective with ending -e: fast (die schnelle Lösung; schnelle Antworten).","ans":1,"inList":1,"ex":[{"x":"Sophie","no":3,"n":31,"de":"Vielen Dank für die 【schnelle】 Zusendung der Informationsmaterialien.","en":"Many thanks for the 【quick】 sending of the information material.","rule":"Für + Akkusativ: für die schnelle Zusendung. After die (feminine Akkusativ) the adjective ends in -e: schnelle."}],"own":null},{"w":"schon","key":"SCHON","ty":"particle","en":"already, (emphasis)","note":"Particle: already (Hast du schon gegessen?); also softens a statement (Das wird schon).","ans":4,"inList":4,"ex":[{"x":"Sophie","no":3,"n":34,"de":"Da ich noch gar keine Erfahrung habe, möchte ich mich 【schon】 jetzt auf das Seminar vorbereiten.","en":"As I have no experience at all, I 【already】 want to prepare for the seminar now.","rule":"Schon jetzt = already now, even now. Meaning decides: the writer wants to prepare before the seminar starts."},{"x":"Andreas","no":6,"n":31,"de":"Ich bin 【schon】 lange Rentner und bekomme monatlich nur wenig Geld.","en":"I have 【already】 been a pensioner for a long time and receive only little money each month.","rule":"Ich bin SCHON lange Rentner = I have already been a pensioner for a long time. Schon expresses 'already'. The meaning decides."},{"x":"Rita","no":18,"n":40,"de":"Ich danke Ihnen 【schon】 jetzt für Ihre Antwort und grüße Sie freundlich.","en":"I thank you 【already】 now for your reply and send kind regards.","rule":"The meaning of the sentence decides. Cross out each word of the list after you use it, because every word is used only once."}],"own":null},{"w":"sehr","key":"SEHR","ty":"adverb","en":"very","note":"Adverb: very (sehr gut), also \"sehr gern\".","ans":1,"inList":2,"ex":[{"x":"Viktor","no":17,"n":35,"de":"Deshalb interessiere ich mich 【sehr】 für Ihre Intensivkurse.","en":"That is why I am 【very】 interested in your intensive courses.","rule":"Sich SEHR interessieren für = to be very interested. Sehr strengthens the verb."}],"own":null},{"w":"seit","key":"SEIT","ty":"preposition","en":"since, for (time)","note":"Preposition + Dativ: since / for (seit drei Jahren, seit Montag). Present tense for something that is still true.","ans":1,"inList":1,"ex":[{"x":"Viktor","no":17,"n":32,"de":"Ich lerne 【seit】 zwei Jahren Deutsch in Yverden, einer kleinen Stadt in der Westschweiz.","en":"I have been learning German 【for】 two years in Yverdon, a small town in western Switzerland.","rule":"SEIT + Dativ: ich lerne seit zwei Jahren Deutsch = for two years (and still). Present tense with seit for a period that continues."}],"own":null},{"w":"sie","key":"SIE","ty":"pronoun","en":"you (formal), she, they","note":"Pronoun: she, they, or Sie = you (formal, capital letter).","ans":0,"inList":1,"ex":[],"own":["Haben Sie morgen Zeit?","Do you have time tomorrow? (formal you)"]},{"w":"soll","key":"SOLL","ty":"modal verb","en":"should, is supposed to","note":"Modal verb, ich/er/sie: should, is supposed to (Ich soll anrufen = they told me to).","ans":0,"inList":1,"ex":[],"own":["Er soll morgen um acht Uhr anrufen.","He is supposed to call at eight o'clock tomorrow."]},{"w":"sollte","key":"SOLLTE","ty":"modal verb","en":"should","note":"Modal verb, Konjunktiv II: should (Sie sollten mehr schlafen = advice).","ans":2,"inList":2,"ex":[{"x":"Sonja","no":9,"n":35,"de":"Was 【sollte】 jeden Tag gegessen werden?","en":"What 【should】 be eaten every day?","rule":"Was SOLLTE jeden Tag gegessen werden? Modal verb in the Konjunktiv II as a recommendation (sollte) + passive infinitive gegessen werden. Question: question word first, then the verb."}],"own":null},{"w":"sondern","key":"SONDERN","ty":"connector","en":"but rather","note":"Connector: but rather, after a negative (nicht heute, sondern morgen).","ans":2,"inList":3,"ex":[{"x":"Sonja","no":9,"n":31,"de":"Die meisten Empfehlungen sind aber nicht für etwas, 【sondern】 gegen etwas, und zwar immer wieder gegen etwas anderes: gegen Fleisch zum Beispiel oder gegen Zucker, aber auch gegen Milch.","en":"Most recommendations, however, are not for something 【but】 against something, and always against something different again: against meat, for example, or against sugar, but also against milk.","rule":"Nicht für etwas, SONDERN gegen etwas: after a negation (nicht) the correction is introduced with sondern. Aber would mean 'but' without the strict correction."}],"own":null},{"w":"sprechen","key":"SPRECHEN","ty":"verb","en":"to speak","note":"Verb: to speak (Ich spreche Deutsch); sprechen über, sprechen mit.","ans":1,"inList":1,"ex":[{"x":"Viktor","no":17,"n":33,"de":"Es gefällt mir hier, aber ich lebe in einer französischsprachigen Region und auch meine Arbeitskollegen 【sprechen】 nur Französisch (oder Englisch) mit mir.","en":"I like it here, but I live in a French-speaking region and my colleagues also 【speak】 only French (or English) with me.","rule":"Meine Arbeitskollegen SPRECHEN nur Französisch: the subject is plural (Kollegen): sprechen. Spricht would be singular."}],"own":null},{"w":"statt","key":"STATT","ty":"preposition","en":"instead of","note":"Preposition: instead of (statt des Autos, statt mir); \"statt … zu\" + infinitive.","ans":2,"inList":2,"ex":[{"x":"Sonja","no":9,"n":37,"de":"Außerdem kann man 【statt】 Milch auch Mineralwasser trinken.","en":"Besides, one can drink mineral water 【instead of】 milk.","rule":"STATT + noun = instead of (Statt Milch). Statt takes the Genitiv, but with a noun without article it is used without an ending. Wegen / ohne do not fit."},{"x":"Carolina","no":10,"n":35,"de":"【Statt】 allein zu spielen, spielen Sie mit uns in einer starken Spielergemeinschaft.","en":"【Instead of】 playing alone, you play with us in a strong community of players.","rule":"STATT allein zu spielen = instead of playing alone. Statt + zu + infinitive. Statt starts the sentence; the verb of the main clause follows in second position."}],"own":null},{"w":"stattfinden","key":"STATTFINDEN","ty":"verb","en":"to take place","note":"Separable verb: to take place (Das Treffen findet am Montag statt).","ans":2,"inList":2,"ex":[{"x":"Jennifer","no":12,"n":32,"de":"Diese Veranstaltung könnte in Breisach 【stattfinden】, und daher brauchen wir von Ihnen nähere Informationen.","en":"This event could 【take place】 in Breisach, and we therefore need further information from you.","rule":"Modal verb könnte + infinitive at the end: Diese Veranstaltung könnte in Breisach STATTFINDEN. Stattfinden is a separable verb, but after a modal it stays together (infinitive)."}],"own":null},{"w":"suchen","key":"SUCHEN","ty":"verb","en":"to look for","note":"Verb: to look for (Ich suche eine Wohnung). Akkusativ object.","ans":1,"inList":1,"ex":[{"x":"Thomas","no":14,"n":37,"de":"Für diese Veranstaltung 【suchen】 wir ein gutes Hotel, möglichst am Ufer des Rheins.","en":"For this event we 【are looking for】 a good hotel, if possible on the bank of the Rhine.","rule":"Wir SUCHEN ein gutes Hotel = we are looking for a hotel (wir + suchen, plural). In this version the question is about the verb."}],"own":null},{"w":"Tage","key":"TAGE","ty":"noun","en":"days","note":"Noun, plural of der Tag: days (in drei Tagen, ein paar Tage).","ans":1,"inList":1,"ex":[{"x":"Eva","no":2,"n":34,"de":"Ich möchte mit meiner Mutter und ihrer Schwester, die beide schon etwas ältere Damen sind, im September ein paar 【Tage】 Urlaub machen und benötige daher einige Informationen.","en":"I would like to go on a few 【days'】 holiday in September with my mother and her sister, who are both rather elderly ladies, and therefore need some information.","rule":"Ein paar Tage: ein paar = a few, followed by a plural noun (Tage, Akkusativ plural). The word list gives the noun, the plural Tage is needed (not the singular Tag)."}],"own":null},{"w":"täglich","key":"TÄGLICH","ty":"adjective","en":"daily","note":"Adjective/adverb: daily, every day.","ans":1,"inList":1,"ex":[{"x":"Andreas","no":6,"n":37,"de":"Einige Fragen hätte ich trotzdem noch: Müssen die Zeitungen 【täglich】 ausgetragen werden und wie lange ist man unterwegs?","en":"I would still have a few questions: do the newspapers have to be delivered 【daily】, and how long are you on the road?","rule":"TÄGLICH = daily (adverb, no ending). Müssen die Zeitungen täglich ausgetragen werden? The meaning decides."}],"own":null},{"w":"technisch","key":"TECHNISCH","ty":"adjective","en":"technical","note":"Adjective/adverb: technical, technically.","ans":0,"inList":1,"ex":[],"own":["Das Gerät ist technisch auf dem neuesten Stand.","The device is technically up to date."]},{"w":"Termin","key":"TERMIN","ty":"noun","en":"appointment","note":"Noun, der Termin: an appointment (einen Termin vereinbaren).","ans":2,"inList":2,"ex":[{"x":"Jennifer","no":12,"n":39,"de":"Der 【Termin】 wäre 15.–21. November.","en":"The 【date】 would be 15–21 November.","rule":"Der TERMIN wäre … = the date would be … Der Termin = masculine noun, subject, with wäre (Konjunktiv II of sein)."},{"x":"Thomas","no":14,"n":39,"de":"Der 【Termin】 wäre 15.-21.","en":"The 【date】 would be 15–21 November.","rule":"Der TERMIN wäre … = the date would be … Der Termin = masculine noun, subject, with wäre (Konjunktiv II of sein)."}],"own":null},{"w":"Tour","key":"TOUR","ty":"noun","en":"tour, trip","note":"Noun, die Tour: a trip, a round (eine Tour durch die Stadt).","ans":0,"inList":1,"ex":[],"own":["Wir machen eine Tour durch die Altstadt.","We are taking a tour of the old town."]},{"w":"trotz","key":"TROTZ","ty":"preposition","en":"despite","note":"Preposition + Genitiv: despite (trotz des Regens); in speech often with Dativ.","ans":0,"inList":1,"ex":[],"own":["Trotz des Regens gehen wir spazieren.","In spite of the rain we go for a walk."]},{"w":"trotzdem","key":"TROTZDEM","ty":"adverb","en":"nevertheless","note":"Adverb: nevertheless. Position 1, verb next (Trotzdem gehe ich).","ans":0,"inList":1,"ex":[],"own":["Es regnet, trotzdem gehen wir spazieren.","It is raining, nevertheless we go for a walk."]},{"w":"über","key":"ÜBER","ty":"preposition","en":"over, about","note":"Preposition: about (sprechen über + Akkusativ), over, above, more than.","ans":0,"inList":2,"ex":[],"own":["Wir sprechen über das Wetter.","We are talking about the weather."]},{"w":"unbekannt","key":"UNBEKANNT","ty":"adjective","en":"unknown","note":"Adjective: unknown, not known (ein unbekannter Absender).","ans":2,"inList":2,"ex":[{"x":"Andreas 2","no":13,"n":36,"de":"Am Anfang war es sehr schwer, weil ich niemanden kannte und alles sehr neu und 【unbekannt】 für mich war.","en":"At the beginning it was very hard, because I knew nobody and everything was very new and 【unfamiliar】 to me.","rule":"Alles sehr neu und UNBEKANNT für mich = unfamiliar. The adjective is used after sein; the same position as neu, so no ending."}],"own":null},{"w":"uns","key":"UNS","ty":"pronoun","en":"us","note":"Pronoun: us (Akkusativ and Dativ of wir): Er ruft uns an; Das gefällt uns.","ans":1,"inList":1,"ex":[{"x":"Vera","no":11,"n":37,"de":"Dagegen macht es 【uns】 viel Spaß.","en":"On the other hand it is a lot of fun for 【us】.","rule":"Das macht UNS viel Spaß: machen takes the Dativ of the person; uns = Dativ of wir. Es macht uns Spaß = it is fun for us."}],"own":null},{"w":"unser","key":"UNSER","ty":"possessive article","en":"our","note":"Possessive article: our (unser Haus). Endings like ein: unsere Wohnung, unserem Haus.","ans":0,"inList":1,"ex":[],"own":["Unser Haus liegt am Stadtrand.","Our house is on the edge of the town."]},{"w":"unter","key":"UNTER","ty":"preposition","en":"under, among","note":"Preposition: under, among (unter den Gästen, unter anderem = among other things).","ans":2,"inList":2,"ex":[{"x":"Nicole","no":5,"n":40,"de":"Ab 19.30 Uhr bin ich telefonisch 【unter】 der Nummer 0428-1734 zu erreichen.","en":"From 19.30 I can be reached by telephone 【on】 the number 0428-1734.","rule":"UNTER + Dativ: unter der Nummer erreichbar. Fixed phrase for phone numbers. Nummer is feminine, Dativ = der."},{"x":"Annika","no":7,"n":36,"de":"Schläft man immer 【unter】 freiem Himmel?","en":"Do you always sleep 【under】 the open sky?","rule":"UNTER freiem Himmel = under the open sky. Unter + Dativ (freiem Himmel), fixed phrase."}],"own":null},{"w":"von","key":"VON","ty":"preposition","en":"of, from, by","note":"Preposition + Dativ: of, from, by (von Montag bis Freitag; ein Brief von meiner Mutter).","ans":1,"inList":1,"ex":[{"x":"Tamara","no":15,"n":37,"de":"Außerdem kann man anstelle 【von】 Milch auch Mineralwasser trinken.","en":"Besides, one can drink mineral water instead 【of】 milk.","rule":"Anstelle VON Milch = instead of milk. Anstelle takes the Genitiv, but with a noun without article you use von + Dativ: anstelle von Milch. Für / wegen do not fit."}],"own":null},{"w":"vor","key":"VOR","ty":"preposition","en":"before, in front of, ago","note":"Preposition: before (vor dem Essen), in front of, \"ago\" (vor zwei Tagen).","ans":2,"inList":6,"ex":[{"x":"Andreas 2","no":13,"n":34,"de":"Länger als ein halbes Jahr habe ich nur einmal im Ausland gelebt, und zwar 【vor】 zwei Jahren.","en":"I have lived abroad for longer than half a year only once, 【two years ago】.","rule":"VOR + Dativ for a time in the past: vor zwei Jahren = two years ago. Vor + Dativ plural (zwei Jahren)."}],"own":null},{"w":"voraus","key":"VORAUS","ty":"adverb","en":"ahead, in advance","note":"Adverb: ahead; im Voraus = in advance (Ich danke Ihnen im Voraus).","ans":1,"inList":1,"ex":[{"x":"Eva","no":2,"n":40,"de":"Ich bedanke mich im 【Voraus】 für die Informationen.","en":"I thank you 【in advance】 for the information.","rule":"Im Voraus = in advance. Fixed phrase (sich im Voraus bedanken = thank in advance), no other word fits."}],"own":null},{"w":"vorne","key":"VORNE","ty":"adverb","en":"at the front","note":"Adverb: at the front. The opposite is hinten.","ans":0,"inList":1,"ex":[],"own":["Bitte setzen Sie sich vorne hin.","Please sit down at the front."]},{"w":"während","key":"WÄHREND","ty":"preposition / connector","en":"during, while","note":"Connector (verb at the end) or preposition + Genitiv: while, during (während des Kurses).","ans":0,"inList":1,"ex":[],"own":["Während ich koche, hört er Musik.","While I cook, he listens to music."]},{"w":"wann","key":"WANN","ty":"question word","en":"when (question)","note":"Question word: when (at what time?) (Wann kommst du?).","ans":2,"inList":5,"ex":[{"x":"Sophie","no":3,"n":37,"de":"Bis 【wann】 muss ich mich spätestens anmelden?","en":"By 【when】 at the latest must I register?","rule":"Bis wann = by when / until when. Wann asks for a time; it matches the bis before the gap (Bis wann muss ich mich anmelden?)."},{"x":"Nicole","no":5,"n":38,"de":"Und 【wann】 finden die Stunden statt?","en":"And 【when】 do the lessons take place?","rule":"WANN = when (question about time): Wann finden die Stunden statt? Question word, then the verb in second place."}],"own":null},{"w":"wäre","key":"WÄRE","ty":"verb (Konjunktiv II)","en":"would be","note":"Konjunktiv II of sein: would be (Es wäre schön, wenn …).","ans":1,"inList":3,"ex":[{"x":"Rita","no":18,"n":34,"de":"Ihre Wohnung 【wäre】 deshalb genau richtig für uns.","en":"Your flat 【would be】 exactly right for us.","rule":"Verb. The subject and the sentence decide the form: Konjunktiv II (würde, könnte, hätte) makes polite requests and unreal wishes, sollte gives advice, kann / muss / darf are the normal modal verbs."}],"own":null},{"w":"wären","key":"WÄREN","ty":"verb (Konjunktiv II)","en":"would be (wir, sie)","note":"Konjunktiv II of sein, wir/sie: would be.","ans":2,"inList":2,"ex":[{"x":"Jennifer","no":12,"n":40,"de":"Für Prospekte und Informationen zu Preisen und Buchungsbedingungen 【wären】 wir Ihnen dankbar.","en":"For brochures and information on prices and booking conditions we 【would be】 grateful.","rule":"Wir WÄREN Ihnen dankbar: polite Konjunktiv II of sein (wir wären). Sein + dankbar + Dativ (Ihnen)."}],"own":null},{"w":"was","key":"WAS","ty":"question word","en":"what","note":"Question word: what (Was machst du?). Also relative: alles, was …","ans":0,"inList":2,"ex":[],"own":["Was machst du am Wochenende?","What are you doing at the weekend?"]},{"w":"wegen","key":"WEGEN","ty":"preposition","en":"because of","note":"Preposition + Genitiv: because of (wegen des Wetters); in speech often with Dativ.","ans":2,"inList":2,"ex":[{"x":"Tamara","no":15,"n":36,"de":"Die einen sagen, Milch ist sehr gesund 【wegen】 der vielen wichtigen Nährstoffe.","en":"Some say milk is very healthy 【because of】 the many important nutrients.","rule":"Wegen der vielen wichtigen Nährstoffe: wegen + Genitiv plural. After der vielen the adjective ends in -en. Wegen = because of (reason)."}],"own":null},{"w":"weil","key":"WEIL","ty":"connector","en":"because","note":"Connector: because. The verb goes to the end (weil ich keine Zeit habe).","ans":5,"inList":5,"ex":[{"x":"Nadja","no":4,"n":32,"de":"Klagenfurt ist für mich der ideale Ort, 【weil】 das nicht so weit weg von meiner Heimatstadt Zagreb ist.","en":"Klagenfurt is the ideal place for me, 【because】 it is not so far from my home town of Zagreb.","rule":"WEIL gives the reason: Klagenfurt ist ideal, weil das nicht so weit weg ist. Weil opens a subordinate clause, verb (ist) at the end."},{"x":"Vera","no":11,"n":32,"de":"Wir wohnen etwa 40 km außerhalb von Nürnberg und schreiben Ihnen, 【weil】 wir Lust hätten, etwas in einer Gruppe zu machen.","en":"We live about 40 km outside Nuremberg and are writing to you 【because】 we would like to do something in a group.","rule":"WEIL = because: wir schreiben Ihnen, weil wir Lust hätten … The reason; the verb (hätten) stands at the end of the subordinate clause."},{"x":"Thomas","no":14,"n":36,"de":"Deshalb erscheint uns Ihre Stadt als sehr geeignet, auch 【weil】 sie als Brücke zu Europa gilt.","en":"Your town therefore seems very suitable to us, also 【because】 it is regarded as a bridge to Europe.","rule":"WEIL = because: auch weil sie als Brücke zu Europa gilt. Weil opens a subordinate clause, the verb (gilt) at the end. Auch weil = also because."}],"own":null},{"w":"welche","key":"WELCHE","ty":"question word","en":"which","note":"Question word: which (feminine/plural: welche Frau, welche Fragen).","ans":1,"inList":1,"ex":[{"x":"Annika","no":7,"n":38,"de":"Ich möchte auch wissen, wie die Reisegruppen zusammengesetzt sind, 【welche】 Sprache die Reiseleiterin/ der Reiseleiter spricht und ob ein Arzt dabei ist.","en":"I would like to know too how the travel groups are put together, 【which】 language the tour guide speaks and whether a doctor is with them.","rule":"Indirect question: wissen, WELCHE Sprache der Reiseleiter spricht. Welche + feminine noun (die Sprache) in the Akkusativ. Which language?"}],"own":null},{"w":"welchen","key":"WELCHEN","ty":"question word","en":"which (Akkusativ / Dativ)","note":"Question word: which (Akkusativ masculine or Dativ plural: welchen Tag, mit welchen Freunden).","ans":2,"inList":2,"ex":[{"x":"Sonja","no":9,"n":34,"de":"Als ich eine Zeitschrift durchsah, ist mir Ihre Anzeige aufgefallen, und nun habe ich folgende Fragen an Sie: Von 【welchen】 Nahrungsmitteln darf man eigentlich so viel essen, wie man will?","en":"When I was looking through a magazine, your advertisement caught my eye, and now I have the following questions for you: of 【which】 foods may one actually eat as much as one wants?","rule":"Von + Dativ plural: von WELCHEN Nahrungsmitteln. Welchen is the Dativ plural form (the noun Nahrungsmittel is plural)."},{"x":"Tamara","no":15,"n":34,"de":"Beim Durchsehen einer Zeitschrift ist mir Ihre Anzeige aufgefallen, und nun habe ich folgende Fragen an Sie: Von 【welchen】 Nahrungsmitteln darf man eigentlich so viel essen, wie man will?","en":"While looking through a magazine your advertisement caught my eye, and now I have the following questions for you: of 【which】 foods may one actually eat as much as one wants?","rule":"Von + Dativ plural: von WELCHEN Nahrungsmitteln. Welchen is the Dativ plural form (the noun Nahrungsmittel is plural)."}],"own":null},{"w":"wenig","key":"WENIG","ty":"quantity word","en":"little, few","note":"Quantity word: little, few (wenig Zeit; ein wenig = a little).","ans":1,"inList":1,"ex":[{"x":"Viktor","no":17,"n":34,"de":"So habe ich einfach zu 【wenig】 Gelegenheit, Deutsch zu sprechen.","en":"So I simply have 【little】 opportunity to speak German.","rule":"Ich habe zu WENIG Gelegenheit = too little. Zu + wenig / viel. Wenig does not take an ending before an uncountable noun (Gelegenheit is missing in the book text)."}],"own":null},{"w":"wenn","key":"WENN","ty":"connector","en":"if, whenever","note":"Connector: if, whenever (condition or repeated event). The verb goes to the end.","ans":6,"inList":6,"ex":[{"x":"Eva","no":2,"n":39,"de":"Ich wäre Ihnen sehr dankbar, 【wenn】 Sie mir Bildmaterial zum Hotel und der Landschaft sowie eine Preisliste zukommen lassen könnten.","en":"I would be very grateful 【if】 you could send me pictures of the hotel and the landscape as well as a price list.","rule":"Ich wäre dankbar, WENN Sie … schicken könnten: polite request. Wenn opens a subordinate clause, verb (könnten) at the end. Combined with wäre / könnten = Konjunktiv II for politeness."},{"x":"Carolina","no":10,"n":34,"de":"Vertrauen Sie beim Lottospiel nicht nur auf das Glück, denn Sie können Ihre Chancen selbst stark verbessern, 【wenn】 Sie mit unserem Lotterie-System spielen – und das für nur 5 Euro in der Woche!","en":"When playing the lottery, do not trust only in luck, because you can greatly improve your chances yourself 【if】 you play with our lottery system – and for only 5 euros a week!","rule":"WENN = if (condition): Sie können Ihre Chancen verbessern, wenn Sie mit uns spielen. Verb (spielen) at the end of the wenn-clause."},{"x":"Rita","no":18,"n":39,"de":"【Wenn】 es möglich ist, würden wir nämlich gerne unseren Hund mitbringen.","en":"【If】 it is possible, we would like to bring our dog.","rule":"Connector. First the meaning (reason, contrast, condition, aim), then the word order: after dass, weil, ob, wenn, damit, obwohl the verb goes to the end; after darum, deshalb, trotzdem the verb comes straight after."}],"own":null},{"w":"werde","key":"WERDE","ty":"verb (helper)","en":"will (ich)","note":"Helper verb, ich: will (Ich werde kommen = future); also \"to become\".","ans":1,"inList":1,"ex":[{"x":"Sophie","no":3,"n":40,"de":"【Werde】 ich auch eine Kursbestätigung am Ende des Seminars erhalten?","en":"【Will】 I also receive a course confirmation at the end of the seminar?","rule":"Future in a question: WERDE ich … erhalten? Werden + infinitive; the question starts with the verb (yes/no), ich werde → werde. The infinitive (erhalten) stands at the end."}],"own":null},{"w":"werden","key":"WERDEN","ty":"verb (helper)","en":"will, to become (wir, sie)","note":"Helper verb, wir/sie: will, to become; also with Partizip II for the passive.","ans":1,"inList":1,"ex":[{"x":"Iris","no":8,"n":33,"de":"Alle Kundendaten 【werden】 selbstverständlich streng vertraulich behandelt.","en":"All customer data 【are】 of course treated strictly confidentially.","rule":"Passive present, plural subject: Alle Kundendaten WERDEN … behandelt. Werden + participle (behandelt) at the end. Haben would need a participle with an active meaning."}],"own":null},{"w":"wichtigen","key":"WICHTIGEN","ty":"adjective","en":"important","note":"Adjective with ending -en: important (mit wichtigen Informationen; den wichtigen Termin).","ans":1,"inList":1,"ex":[{"x":"Sonja","no":9,"n":36,"de":"Die einen sagen, Milch ist sehr gesund wegen der vielen 【wichtigen】 Nährstoffe.","en":"Some say milk is very healthy because of the many 【important】 nutrients.","rule":"Wegen der vielen WICHTIGEN Nährstoffe: wegen + Genitiv plural. After der vielen the adjective ends in -en. Compare Dativ plural: mit den wichtigen Nährstoffen."}],"own":null},{"w":"wie","key":"WIE","ty":"question word / comparison","en":"how, as, like","note":"Question word: how (Wie geht es dir?); also comparison: so groß wie.","ans":4,"inList":5,"ex":[{"x":"Nadja","no":4,"n":39,"de":"Wenn Sie einen passenden Kurs für mich haben, schicken Sie mir bitte sobald 【wie】 möglich nähere Informationen zu.","en":"If you have a suitable course for me, please send me further information as soon as 【possible】.","rule":"So bald WIE möglich = as soon as possible. Fixed comparison so … wie."},{"x":"Andreas","no":6,"n":38,"de":"Außerdem möchte ich natürlich wissen, 【wie】 man verdient.","en":"I would of course also like to know 【how much】 one earns.","rule":"Wissen, WIE man verdient: indirect question with the question word wie; verb at the end (verdient)."},{"x":"Viktor","no":17,"n":38,"de":"【Wie】 viele Studenten nehmen an einem Kurs teil?","en":"【How many】 students take part in a course?","rule":"WIE viele = how many (question word, the number of students). Wie + viele + plural noun. The word list of this exam contains WIE twice."}],"own":null},{"w":"wissen","key":"WISSEN","ty":"verb","en":"to know (a fact)","note":"Verb: to know a fact (Wir wissen es). For people and places use kennen.","ans":0,"inList":1,"ex":[],"own":["Wir wissen noch nicht, wann er kommt.","We do not know yet when he is coming."]},{"w":"wo","key":"WO","ty":"question word","en":"where","note":"Question word: where (Wo wohnst du?).","ans":1,"inList":1,"ex":[{"x":"Rita","no":18,"n":36,"de":"Und gibt es in der näheren Umgebung einen Spielplatz, 【wo】 mein Sohn spielen könnte?","en":"And is there a playground nearby 【where】 my son could play?","rule":"Question word. It must fit the noun or verb that follows (welchen + plural noun with von, wie viel / wie viele, wann)."}],"own":null},{"w":"Wochenende","key":"WOCHENENDE","ty":"noun","en":"weekend","note":"Noun, das Wochenende: the weekend (am Wochenende, übers Wochenende).","ans":1,"inList":1,"ex":[{"x":"Eva","no":2,"n":31,"de":"Ich habe Ihre Anzeige in der Zeitung vom letzten 【Wochenende】 gelesen und interessiere mich sehr für das Angebot.","en":"I read your advertisement in the newspaper of last 【weekend】 and am very interested in the offer.","rule":"Von + Dativ: in der Zeitung vom (= von dem) letzten Wochenende. Wochenende is neuter, Dativ: the adjective letzten has -en and the noun is unchanged."}],"own":null},{"w":"würde","key":"WÜRDE","ty":"verb (Konjunktiv II)","en":"would (ich, er/sie/es)","note":"Konjunktiv II helper, ich/er/sie: would + infinitive at the end (Ich würde gern kommen).","ans":4,"inList":4,"ex":[{"x":"Sonja","no":9,"n":39,"de":"Das Thema Essen und Sport 【würde】 mich besonders interessieren, weil ich selber viel Sport treibe.","en":"The subject of food and sport 【would】 interest me especially, because I do a lot of sport myself.","rule":"WÜRDE mich besonders interessieren: Konjunktiv II, würde + infinitive interessieren. Subject: das Thema (singular) → würde."},{"x":"Andreas 2","no":13,"n":39,"de":"Ich glaube, dass meine Erfahrungen für viele andere Menschen, die auch im Ausland leben wollen, sehr interessant sein könnten, und ich 【würde】 gerne auch vor der Kamera darüber erzählen.","en":"I believe that my experiences could be very interesting for many other people who also want to live abroad, and I 【would】 gladly talk about them in front of the camera too.","rule":"Ich WÜRDE gerne darüber erzählen = Konjunktiv II for a polite wish: würde + infinitive (erzählen) at the end. Würde = 1st / 3rd person singular."}],"own":null},{"w":"würden","key":"WÜRDEN","ty":"verb (Konjunktiv II)","en":"would (wir, sie)","note":"Konjunktiv II helper, wir/sie: would + infinitive at the end.","ans":1,"inList":2,"ex":[{"x":"Vera","no":11,"n":38,"de":"Daher 【würden】 wir uns auch auf gemeinsame Radtouren hier bei uns freuen.","en":"So we 【would】 also look forward to joint bike tours here with us.","rule":"Daher WÜRDEN wir uns freuen = Konjunktiv II with a polite wish. After daher the verb comes next (würden wir); the infinitive (freuen) at the end."}],"own":null},{"w":"zu","key":"ZU","ty":"preposition","en":"to, too","note":"Preposition + Dativ: to (zu meiner Freundin), too (zu teuer); also before an infinitive (Ich habe keine Zeit, zu kommen).","ans":0,"inList":2,"ex":[],"own":["Das Hotel ist zu teuer für mich.","The hotel is too expensive for me."]},{"w":"zum","key":"ZUM","ty":"preposition","en":"to the, for the","note":"zu + dem: to the (zum Arzt), for (zum Frühstück), \"zum Beispiel\".","ans":0,"inList":2,"ex":[],"own":["Zum Frühstück esse ich Brot mit Käse.","For breakfast I eat bread with cheese."]},{"w":"zwar","key":"ZWAR","ty":"particle","en":"indeed, admittedly","note":"Particle: indeed, admittedly; comes with aber (Es ist zwar teuer, aber gut).","ans":1,"inList":1,"ex":[{"x":"Andreas","no":6,"n":33,"de":"Ich bin 【zwar】 schon 72 Jahre alt, aber noch bei sehr guter Gesundheit.","en":"I 【am indeed】 already 72 years old, but still in very good health.","rule":"ZWAR … aber: Ich bin zwar schon 72, aber noch gesund. Zwar introduces a concession that aber then contrasts."}],"own":null},{"w":"zwischen","key":"ZWISCHEN","ty":"preposition","en":"between","note":"Preposition: between (zwischen den Häusern, zwischen 8 und 9 Uhr).","ans":0,"inList":2,"ex":[],"own":["Das Büro liegt zwischen der Bank und dem Bahnhof.","The office is between the bank and the station."]}],"t1":[{"key":"prep","title":"Prepositions","rule":"Learn the pair: verb + preposition (warten auf, um etwas bitten, sich freuen über), time words (bis, seit, vor, ab) and the case after the preposition. Look at the word before the gap.","items":[{"x":"Petra","no":1,"n":24,"a":"Bis","o":["Bis","Nach","Von"],"de":"【Bis】 spät abends höre ich nun täglich den Lärm der Restaurantsgäste im Garten.","en":"【Until】 late in the evening I now hear the noise of the restaurant guests in the garden every day.","rule":"Bis spät abends = until late in the evening. Bis + a time expression, no article. Nach = after a point in time (nach dem Essen), von needs bis (von … bis).","od":["until. Bis spät abends = until late in the evening; bis goes with a time and has no article.","after. It needs a point in time or an event (nach dem Essen); \"after late in the evening\" makes no sense.","from. It only works with bis (von morgens bis abends), and no bis follows here."]},{"x":"Petra","no":1,"n":27,"a":"im","o":["im","in","ins"],"de":"Außerdem fühle ich mich 【im】 Haus nicht mehr sicher, weil das Restaurant oft die ganze Nacht geöffnet hat.","en":"Besides, I no longer feel safe 【in the】 building, because the restaurant is often open all night.","rule":"Sich sicher fühlen im Haus: the place where I am = in + Dativ, in dem = im. In / ins would be movement into the house (Akkusativ).","od":["in the (in dem). Where does she feel safe? In the house: in + Dativ = im Haus.","in. A noun like Haus needs an article here; \"in Haus\" is not correct German.","into the (in das, Akkusativ). That is movement into the house (ins Haus gehen), not the place where she feels safe."]},{"x":"Sophie","no":3,"n":21,"a":"seit","o":["ab","seit","vor"],"de":"Wir wohnen jetzt schon 【seit】 sechs Wochen in unserer neuen Wohnung.","en":"We have now been living 【for】 six weeks in our new flat.","rule":"Seit + Dativ for a period that began in the past and still continues, with the present tense: wir wohnen seit sechs Wochen. Ab = from a point in the future, vor sechs Wochen would mean ago (with past tense).","od":["from (a starting point). It looks forward (ab nächster Woche); here the period began in the past.","since, for. The period began in the past and still continues, with the present tense: wir wohnen seit sechs Wochen.","ago. vor sechs Wochen = six weeks ago, for a past event with the past tense, not for something still going on."]},{"x":"Nicole","no":5,"n":27,"a":"für","o":["für","von","wegen"],"de":"Sie finden darin viele nützliche und attraktive Dinge rund um das Thema Kaffee und Trinkwasser 【für】 Mitarbeiter und Besucher.","en":"In it you will find many useful and attractive things around the subject of coffee and drinking water 【for】 employees and visitors.","rule":"Book key says von, but the meaning is for: Kaffee und Trinkwasser FÜR Mitarbeiter und Besucher (the people who get the coffee). Für + Akkusativ. Von would mean 'from employees', wegen = because of.","od":["for. Kaffee und Trinkwasser für Mitarbeiter und Besucher: for whom? (für + Akkusativ).","from, of. It would mean \"from employees\"; the book key says von, but it does not fit the meaning.","because of. It gives a cause, not the people who get the coffee."]},{"x":"Andreas","no":6,"n":22,"a":"zum","o":["zu","zum","zur"],"de":"Wir müssen Informationen 【zum】 Thema Gesundheit und Ernährung suchen und schauen, was es dazu Interessantes im Internet gibt.","en":"We have to look for information 【on】 the subject of health and nutrition and see what interesting things there are about it on the internet.","rule":"Zu + Dativ: Informationen zum Thema = zu dem Thema (Thema is neuter, Dativ). Zur = zu der (feminine), zu alone cannot stand before a noun with article.","od":["to. It cannot stand in front of Thema with an article; the article has to be contracted.","to the (zu dem, Dativ neuter). Informationen zum Thema: zu + Dativ.","to the (zu der, feminine). Thema is neuter, so zur is wrong."]},{"x":"Andreas","no":6,"n":23,"a":"im","o":["am","im","mit"],"de":"Wir müssen Informationen zum Thema Gesundheit und Ernährung suchen und schauen, was es dazu Interessantes 【im】 Internet gibt.","en":"We have to look for information on the subject of health and nutrition and see what interesting things there are about it 【on the】 internet.","rule":"Im Internet = in dem Internet: in + Dativ, where? (on the internet). Am would be an dem (for surfaces), mit does not fit the meaning.","od":["on the (an dem). It is used for surfaces and days, not for the internet.","in the (in dem). Where is it? In the internet: in + Dativ.","with. It does not fit \"something interesting … the internet\"."]},{"x":"Annika","no":7,"n":21,"a":"in","o":["auf","in","über"],"de":"Zum Start 【in】 das neue Geschäftsjahr haben wir uns für Sie etwas ganz Besonders ausgedacht: einen attraktiven Gewinn!","en":"For the start 【of】 the new financial year we have thought of something quite special for you: an attractive prize!","rule":"Zum Start IN das neue Geschäftsjahr: movement into something new, in + Akkusativ (das neue Geschäftsjahr). Auf / über do not fit the noun Start.","od":["on. \"zum Start auf\" is not used here.","in (Akkusativ). zum Start in das neue Geschäftsjahr: into the new business year (movement into a new period).","over, about. It has no meaning of beginning something new."]},{"x":"Annika","no":7,"n":22,"a":"Mit","o":["Mit","Von","Zwischen"],"de":"【Mit】 dem Beginn des neuen Geschäftsjahres feiern wir unsere erfolgreiche Buchidee.","en":"【With】 the beginning of the new financial year we celebrate our successful book idea.","rule":"MIT dem Beginn = with the beginning. Mit + Dativ (dem Beginn). Zwischen needs two things, von needs bis.","od":["with. Mit dem Beginn = with the beginning; mit + Dativ.","from. It needs bis (von … bis).","between. It needs two things (zwischen A und B)."]},{"x":"Annika","no":7,"n":27,"a":"teil","o":["mit","teil","zu"],"de":"Gleichzeitig nehmen Sie an einem Preisausschreiben 【teil】.","en":"At the same time you 【take part】 in a prize draw.","rule":"Teilnehmen an + Dativ is a separable verb: Sie nehmen an einem Preisausschreiben TEIL (the prefix goes to the end). Mit / zu do not form this verb.","od":["with. It would form a different verb (mitnehmen = take along) and change the meaning.","part (separable prefix). teilnehmen an: Sie nehmen an einem Preisausschreiben teil; the prefix goes to the end.","to, closed. zunehmen = to increase, a different verb."]},{"x":"Annika","no":7,"n":28,"a":"unter","o":["unter","neben","vor"],"de":"Bitte beachten Sie: Sollte Ihre Kundennummer 【unter】 den richtigen Zahlen sein, haben Sie die Chance, ein Auto, eine Reise und viele weitere Preise zu erhalten.","en":"Please note: if your customer number is 【among】 the right numbers, you have the chance to win a car, a trip and many other prizes.","rule":"Book key says neben, but the meaning is among: Sollte Ihre Kundennummer UNTER den richtigen Zahlen sein = among the right numbers. Unter + Dativ plural (den Zahlen). Neben = next to, which makes no sense for a customer number.","od":["among. unter den richtigen Zahlen: unter + Dativ plural. (The book key says neben, which makes no sense here.)","next to. It describes a physical position, not \"among\".","before, in front of. It does not fit \"among the right numbers\"."]},{"x":"Iris","no":8,"n":21,"a":"bei","o":["bei","nach","zu"],"de":"Nächste Woche werde ich also 【bei】 dir in Berlin sein.","en":"Next week I will therefore be 【with】 you in Berlin.","rule":"BEI dir = at your place (with you). Bei + Dativ (dir). Nach + city or direction, zu + person = movement.","od":["at (someone's place). bei dir = at your place, with you (bei + Dativ).","to. nach goes with cities and countries (nach Berlin), not with a person.","to. zu + person means movement towards someone; here the writer will already be at the person's place."]},{"x":"Sonja","no":9,"n":27,"a":"um","o":["über","um","vor"],"de":"Nun bitte ich dich 【um】 ein paar gute Tipps.","en":"Now I ask you 【for】 a few good tips.","rule":"Bitten UM + Akkusativ: fixed pair (ich bitte dich um Tipps). Learn bitten um, the preposition is fixed.","od":["about. \"bitten über\" is not a fixed pair.","for. bitten um + Akkusativ: ich bitte dich um Tipps.","before, in front of. It does not go with bitten."]},{"x":"Sonja","no":9,"n":30,"a":"in","o":["bis","in","an"],"de":"Geht das vielleicht 【in】 zwei Wochen, zum Beispiel am übernächsten Wochenende?","en":"Might that be possible 【in】 two weeks, for example the weekend after next?","rule":"IN + Dativ for a future time: in zwei Wochen = two weeks from now. Bis would mean 'until', an = at a point (an einem Tag).","od":["until. It gives a limit, not a time counted from now.","in. in zwei Wochen = in two weeks' time (in + Dativ for a future time span).","on, at. It is for a point or a day (an einem Tag), not for \"in two weeks\"."]},{"x":"Carolina","no":10,"n":24,"a":"für","o":["an","für","vor"],"de":"Das ist 【für】 mich fast unglaublich!","en":"That is almost unbelievable 【for】 me!","rule":"Das ist FÜR mich fast unglaublich = for me. Für + Akkusativ (mich). An / vor do not fit.","od":["at, on. It does not fit this meaning.","for. Das ist für mich unglaublich: für + Akkusativ (mich).","before, in front of. It is not used with this meaning."]},{"x":"Vera","no":11,"n":21,"a":"am","o":["am","in","zum"],"de":"Wie du ja weißt, sind meine Eltern seit Anfang Mai in einem Haus 【am】 Mittelmeer in Spanien.","en":"As you know, my parents have been in a house 【on】 the Mediterranean in Spain since the beginning of May.","rule":"AM Mittelmeer: am = an dem; with seas and rivers an + Dativ (at the sea). In / zum do not fit the meaning.","od":["at the (an dem). With seas and rivers: am Mittelmeer.","in. It is not used for the coast of a sea.","to the (zu dem). It means movement towards; here a place is meant."]},{"x":"Vera","no":11,"n":30,"a":"Bis","o":["Ab","Bis","Seit"],"de":"【Bis】 jetzt habe ich jede Woche von ihnen gehört.","en":"【Up to】 now I have heard from them every week.","rule":"BIS jetzt = until now, up to now. Ab / seit would not fit the Perfekt habe ich … gehört with jede Woche.","od":["from (a starting point). ab jetzt looks forward; it does not fit the Perfekt habe ich gehört.","until. bis jetzt = until now.","since. seit needs a point in time (seit gestern); \"seit jetzt\" is not used."]},{"x":"Jennifer","no":12,"n":24,"a":"für","o":["durch","für","mit"],"de":"Oder es gibt Angebote mit Schiffen, die das Rad 【für】 wenig Geld transportieren.","en":"Or there are offers with boats that carry the bike 【for】 little money.","rule":"Das Rad FÜR wenig Geld transportieren = for little money (price). Für + Akkusativ with the price. Durch / mit do not describe payment.","od":["through, by. It is for a route or means, not for a price.","for. das Rad für wenig Geld transportieren: für + Akkusativ with a price.","with. It means using something; the price paid is expressed with für."]},{"x":"Jennifer","no":12,"n":26,"a":"am","o":["am","im","zum"],"de":"Schon 【am】 Hafen sind mir die vielen Fahrräder aufgefallen.","en":"Already 【at the】 harbour I noticed the many bicycles.","rule":"Am Hafen = an dem Hafen: an + Dativ (where? at the harbour). Im / zum do not fit.","od":["at the (an dem). am Hafen = at the harbour.","in the (in dem). It would mean inside the harbour, in the water.","to the (zu dem). It means movement towards the harbour."]},{"x":"Thomas","no":14,"n":24,"a":"mit","o":["für","mit","zu"],"de":"Obwohl ich ausdrücklich einen Direktflug nach Mumbai bestellt hatte, haben Sie mir Tickets 【mit】 Zwischenstopp in Delhi ausgestellt.","en":"Although I had expressly ordered a direct flight to Mumbai, you issued me tickets 【with】 a stopover in Delhi.","rule":"MIT Zwischenstopp = with a stopover. Mit + noun without article (accusative/dative not visible). Für / zu do not express 'with'.","od":["for. It does not express \"with a stopover\".","with. Tickets mit Zwischenstopp.","to. It means movement or purpose, not \"with\"."]},{"x":"Thomas","no":14,"n":28,"a":"um","o":["für","um","zu"],"de":"Ich darf Sie daher 【um】 Rückzahlung der zu viel verrechneten Kosten auf mein Konto bei der Bank of India in Mumbai bitten.","en":"I therefore ask you 【for】 a refund of the overcharged costs to my account at the Bank of India in Mumbai.","rule":"Bitten UM + Akkusativ: ich darf Sie um Rückzahlung bitten. Fixed verb + preposition pair (bitten um).","od":["for. bitten für is not a fixed pair.","for. bitten um + Akkusativ: ich darf Sie um Rückzahlung bitten.","to. It does not go with bitten."]},{"x":"Thomas","no":14,"n":29,"a":"bei","o":["an","bei","vor"],"de":"Ich darf Sie daher um Rückzahlung der zu viel verrechneten Kosten auf mein Konto 【bei】 der Bank of India in Mumbai bitten.","en":"I therefore ask you for a refund of the overcharged costs to my account 【at】 the Bank of India in Mumbai.","rule":"Das Konto BEI + Dativ: bei der Bank = at the bank. Bei der Bank of India (Dativ feminine). An / vor are not used with Konto + Bank.","od":["at, on. It is not used with a bank account.","at. Konto bei der Bank (bei + Dativ).","in front of. It does not fit."]},{"x":"Tamara","no":15,"n":24,"a":"mit","o":["für","mit","zu"],"de":"Obwohl ich ausdrücklich einen Direktflug nach Mumbai bestellt hatte, haben Sie mir einen Flug 【mit】 Zwischenstopp in Delhi ausgestellt.","en":"Although I had expressly ordered a direct flight to Mumbai, you issued me a flight 【with】 a stopover in Delhi.","rule":"MIT Zwischenstopp = with a stopover. Mit + noun without article (accusative/dative not visible). Für / zu do not express 'with'.","od":["for. It does not express \"with a stopover\".","with. Tickets mit Zwischenstopp.","to. It means movement or purpose, not \"with\"."]},{"x":"Tamara","no":15,"n":28,"a":"um","o":["für","um","zu"],"de":"Ich darf Sie daher 【um】 Rückzahlung der zu viel verrechneten Kosten auf mein Konto bei der Deutschen Bank in Mumbai bitten.","en":"I therefore ask you 【for】 a refund of the overcharged costs to my account at the Deutsche Bank in Mumbai.","rule":"Bitten UM + Akkusativ: ich darf Sie um Rückzahlung bitten. Fixed verb + preposition pair (bitten um).","od":["for. bitten für is not a fixed pair.","for. bitten um + Akkusativ: ich darf Sie um Rückzahlung bitten.","to. It does not go with bitten."]},{"x":"Tamara","no":15,"n":29,"a":"bei","o":["an","bei","vor"],"de":"Ich darf Sie daher um Rückzahlung der zu viel verrechneten Kosten auf mein Konto 【bei】 der Deutschen Bank in Mumbai bitten.","en":"I therefore ask you for a refund of the overcharged costs to my account 【at】 the Deutsche Bank in Mumbai.","rule":"Das Konto BEI + Dativ: bei der Bank = at the bank. Bei der Bank of India (Dativ feminine). An / vor are not used with Konto + Bank.","od":["at, on. It is not used with a bank account.","at. Konto bei der Bank (bei + Dativ).","in front of. It does not fit."]},{"x":"Jan","no":16,"n":28,"a":"unter","o":["unter","neben","vor"],"de":"Bitte beachten Sie: sollte Ihre Kundennummer 【unter】 den richtigen Zahlen sein, haben Sie die Chance, ein Auto eine Reise und viele weitere Preise zu erhalten.","en":"Please note: if your customer number is 【next to】 the right numbers, you have the chance to win a car, a trip and many other prizes.","rule":"Book key says neben, but the meaning is among: Sollte Ihre Kundennummer UNTER den richtigen Zahlen sein = among the right numbers. Unter + Dativ plural (den Zahlen). Neben = next to, which makes no sense for a customer number.","od":["among. unter den richtigen Zahlen: unter + Dativ plural. (The book key says neben, which makes no sense here.)","next to. It describes a physical position, not \"among\".","before, in front of. It does not fit \"among the right numbers\"."]},{"x":"Rita","no":18,"n":25,"a":"bei","o":["an","bei","zu"],"de":"Aber zum Glück hat eine davon gepasst: Ich werde nun zwei Nachmittage in der Woche als Babysitterin 【bei】 einer Familie arbeiten, die zwei Kinder hat.","en":"But luckily one of them worked out: I will now work two afternoons a week as a babysitter 【for】 a family that has two children.","rule":"Preposition. Prepositions are fixed with verbs, nouns or times (warten auf, sich freuen über, bis / in / an + time). Look at the word before the gap and learn the pair.","od":["at, on. It is not used for working for a family.","at, with. bei einer Familie arbeiten (bei + Dativ).","to. It means movement, not working for someone."]},{"x":"Rita","no":18,"n":28,"a":"ins","o":["im","in","ins"],"de":"Wir haben in der ersten Woche bereits Vieles gemeinsam gemacht, sind in den Zoo und 【ins】 Kindermuseum gegangen.","en":"In the first week we have already done a lot together, we went to the zoo and 【to the】 children’s museum.","rule":"Preposition. Prepositions are fixed with verbs, nouns or times (warten auf, sich freuen über, bis / in / an + time). Look at the word before the gap and learn the pair.","od":["in the (in dem). It would mean a place where, not where to.","in. It needs an article here.","into the (in das). Movement into the museum: wohin? Akkusativ."]},{"x":"Grenzacker","no":19,"n":23,"a":"für","o":["an","für","in"],"de":"Nochmals vielen Dank für die selbst gebackenen Kekse, die Sie mir bei unserem letzten Treffen 【für】 die Reise mitgegeben haben.","en":"Once again many thanks for the home-baked biscuits that you gave me 【for】 the journey when we last met.","rule":"für die Reise = for the journey. An and in do not fit mitgeben + Reise.","od":["on, at (an). It does not go with mitgeben and die Reise.","for (für). mitgeben für die Reise = to give something for the journey.","in (in). \"in die Reise\" does not fit: you do not go into a journey."]}]},{"key":"conj","title":"Connectors","rule":"Meaning first (reason weil, aim damit, condition wenn / falls, contrast obwohl / aber / sondern). Then the word order: after weil, dass, ob, wenn, obwohl, damit, falls the verb goes to the end.","items":[{"x":"Eva","no":2,"n":21,"a":"dass","o":["darum","dass","weil"],"de":"Schade, 【dass】 Sie CHIP nicht weiter beziehen möchten.","en":"We are sorry 【that】 you want to stop receiving CHIP.","rule":"Schade, DASS Sie … nicht beziehen möchten: after an expression of feeling (schade, ich freue mich) the content is introduced with dass; the verb goes to the end. Darum / weil would give a different meaning (reason, result).","od":["therefore, adverb of result. It does not introduce what is a pity, and it does not send the verb to the end.","that, conjunction. After schade (it is a pity) the content follows with dass, verb at the end.","because. It gives a reason, but schade needs what is a pity, not why."]},{"x":"Eva","no":2,"n":26,"a":"trotzdem","o":["obwohl","trotz","trotzdem"],"de":"Wir verlieren Sie natürlich nur ungern als Abonnenten und würden uns freuen, wenn Sie CHIP 【trotzdem】 ab und zu am Kiosk kaufen.","en":"Of course we lose you as a subscriber only reluctantly and would be pleased if you 【still】 bought CHIP at the kiosk now and then.","rule":"Book key says trotz, but trotz needs a noun (trotz des Wetters, Genitiv). Here an adverb is needed: wenn Sie CHIP TROTZDEM ab und zu kaufen = nevertheless. Obwohl would send the verb to the end of its own clause.","od":["although, connector. It sends the verb to the end of its own clause, which does not fit \"wenn Sie CHIP … kaufen\".","despite, preposition. It needs a noun after it (trotz des Wetters), but none follows.","nevertheless, adverb. It stands inside the clause: wenn Sie CHIP trotzdem ab und zu kaufen. (The book key says trotz, but that does not fit.)"]},{"x":"Eva","no":2,"n":28,"a":"Falls","o":["Aber","Falls","Wann"],"de":"【Falls】 Sie noch Fragen haben oder sich wieder für ein Abonnement entscheiden, stehen wir Ihnen gerne unter der Nummer 0781/639 6259 von montags bis freitags von 8 bis 18 Uhr zur Verfügung.","en":"【If】 you have more questions or decide on a subscription again, we are happy to be at your service on the number 0781/639 6259, Monday to Friday from 8 to 18.","rule":"Falls = in case / if. It opens a subordinate clause: Falls Sie Fragen haben, the verb (haben) at the end. Aber would keep the main-clause word order (verb second), Wann is a question word.","od":["but. It contrasts and keeps main-clause word order; here a condition with the verb at the end is needed.","in case, if. It opens a subordinate clause: Falls Sie Fragen haben (verb haben at the end).","when (question word). It asks for a time; it does not state a condition."]},{"x":"Nicole","no":5,"n":21,"a":"dass","o":["dass","darum","weil"],"de":"Schade, 【dass】 Sie bisher noch nicht Kunde bei Kaffee Partner sind.","en":"We are sorry 【that】 you are not yet a customer of Kaffee Partner.","rule":"Book key says darum, but it cannot be: schade, DASS Sie noch nicht Kunde sind. After schade (a feeling) the content follows with dass, the verb (sind) at the end. Darum = that is why and would need a main clause; weil gives a reason, which is not meant.","od":["that. After schade (it is a pity) the content follows with dass; the verb (sind) goes to the end.","therefore. It is an adverb of result and would need a reason before it.","because. It gives a reason, but schade needs what is a pity, not why."]},{"x":"Iris","no":8,"n":24,"a":"Aber","o":["Aber","Sondern","Trotzdem"],"de":"【Aber】 ich würde gern auch mal wieder in eine richtige Disko gehen.","en":"【But】 I would like to go to a proper disco again too.","rule":"ABER marks the contrast with the previous sentence (living in the country is nice, BUT I would like to dance). Sondern needs a negation first, trotzdem needs a result.","od":["but. It marks the contrast with the previous sentence (country life is nice, but I want to dance).","but rather. It is only used after a negation (nicht A, sondern B).","nevertheless. It sends the verb straight after it (Trotzdem würde ich …), but the text goes on with ich würde."]},{"x":"Iris","no":8,"n":28,"a":"wann","o":["als","wann","wenn"],"de":"Leider habe ich noch keine Ahnung, 【wann】 ich in Berlin ankommen werde.","en":"Unfortunately I do not yet have any idea 【when】 I will arrive in Berlin.","rule":"WANN = when (question word): keine Ahnung, wann ich ankomme. Indirect question with a question word, the verb (werde) at the end. Als / wenn do not ask for a time.","od":["when (one single time in the past). Not for a question about a future arrival.","when (question word). An indirect question about the time: keine Ahnung, wann ich ankommen werde.","if, whenever. It gives a condition, not an indirect question about the time."]},{"x":"Sonja","no":9,"n":26,"a":"damit","o":["als","damit","ob"],"de":"Aber ein bisschen Glück braucht man auch, 【damit】 so etwas gelingt.","en":"But one also needs a bit of luck 【so that】 something like this works out.","rule":"DAMIT = so that, expresses the aim: ein bisschen Glück, damit so etwas gelingt. Damit opens a subordinate clause (verb gelingt at the end). Als / ob do not fit the meaning.","od":["when, than, as. It does not express an aim.","so that. It expresses the aim and sends the verb to the end: damit so etwas gelingt.","whether. It is used for indirect yes/no questions."]},{"x":"Carolina","no":10,"n":23,"a":"aber","o":["aber","obwohl","sondern"],"de":"【aber】 in jeder Gegend wird ein anderer Dialekt oder gar eine andere Sprache gesprochen.","en":"【But】 in every region a different dialect or even a different language is spoken.","rule":"ABER marks the contrast to the previous sentence (Switzerland is not big. BUT in every region …). Obwohl would open a subordinate clause, sondern needs a negation first.","od":["but. It marks the contrast with the previous sentence.","although. It would send the verb to the end of its clause, but here the verb comes second.","but rather. It is only used after a negation."]},{"x":"Carolina","no":10,"n":25,"a":"wenn","o":["als","wann","wenn"],"de":"Bei uns in Australien fährt man mit dem Auto 24 Stunden lang geradeaus, und 【wenn】 man ankommt, dann sprechen die Leute dort immer noch dieselbe Sprache.","en":"At home in Australia you drive straight ahead by car for 24 hours, and 【when】 you arrive, the people there still speak the same language.","rule":"WENN man ankommt = whenever one arrives (a general, repeating event in the present). Als = one past event, wann = question word.","od":["when (one single time in the past). This sentence is about something general in the present.","when (question word). It asks for a time.","whenever, if. A general, repeated event: wenn man ankommt."]},{"x":"Vera","no":11,"n":26,"a":"obwohl","o":["aber","obwohl","trotz"],"de":"Ich bin sehr zufrieden, 【obwohl】 mein Zimmer recht klein ist.","en":"I am very satisfied, 【although】 my room is quite small.","rule":"OBWOHL = although, concession: ich bin zufrieden, obwohl mein Zimmer klein ist. Obwohl opens a subordinate clause (verb ist at the end). Trotz needs a noun, aber a main clause.","od":["but. The verb ist is at the end, so a subordinating connector is needed.","although. It opens a subordinate clause (verb ist at the end).","despite. It needs a noun (trotz des Zimmers), not a clause."]},{"x":"Vera","no":11,"n":29,"a":"Oder","o":["Damit","Oder","Sondern"],"de":"【Oder】 sie rufen an.","en":"【Or】 they phone.","rule":"ODER connects two possibilities (Sometimes an e-mail. OR they phone). Damit would give an aim, sondern needs a negation.","od":["so that. It opens a clause with the verb at the end, but here the verb is in second place.","or. Oder connects two possibilities (an e-mail, or they phone).","but rather. It is only used after a negation."]},{"x":"Jennifer","no":12,"n":27,"a":"Außerdem","o":["Aber","Außer","Außerdem"],"de":"【Außerdem】 gibt es Markierungen auf den Straßen, die den Radfahrern erlauben, sich bei roten Ampeln vor die Autos zu stellen.","en":"【Besides,】 there are markings on the streets that allow cyclists to stand in front of the cars at red lights.","rule":"AUSSERDEM = besides, in addition: it adds a further point and starts the main clause (Außerdem gibt es …, verb in second place). Außer is a preposition (außer dir), aber = but.","od":["but. It marks a contrast; here a further point is added.","except. It is a preposition (außer dir) and does not open a sentence this way.","besides. An adverb that adds a point; the verb comes straight after it."]},{"x":"Thomas","no":14,"n":23,"a":"Obwohl","o":["Danach","Obwohl","Nämlich"],"de":"【Obwohl】 ich ausdrücklich einen Direktflug nach Mumbai bestellt hatte, haben Sie mir Tickets mit Zwischenstopp in Delhi ausgestellt.","en":"【Although】 I had expressly ordered a direct flight to Mumbai, you issued me tickets with a stopover in Delhi.","rule":"OBWOHL = although, concession: Obwohl ich einen Direktflug bestellt hatte, haben Sie mir Tickets mit Zwischenstopp ausgestellt. Verb hatte at the end of the obwohl-clause, then the main clause starts with the verb (haben Sie).","od":["afterwards. An adverb; the verb would follow straight after it, but hatte is at the end.","although. Concession: Obwohl ich einen Direktflug bestellt hatte, …","namely, you see. A particle inside a sentence; it does not open a clause."]},{"x":"Thomas","no":14,"n":26,"a":"sondern","o":["besonders","sondern","sonst"],"de":"Die Tickets waren nämlich nicht nur anders als vereinbart, 【sondern】 auch noch viel teurer.","en":"The tickets were not only different from what was agreed, 【but】 also much more expensive.","rule":"Nicht nur …, SONDERN auch …: after a negation (nicht nur) the correction is introduced with sondern. Besonders = especially, sonst = otherwise.","od":["especially. It does not fit nicht nur ….","but rather. nicht nur …, sondern auch.","otherwise. It gives an alternative or condition."]},{"x":"Tamara","no":15,"n":23,"a":"Obwohl","o":["Danach","Obwohl","Nämlich"],"de":"【Obwohl】 ich ausdrücklich einen Direktflug nach Mumbai bestellt hatte, haben Sie mir einen Flug mit Zwischenstopp in Delhi ausgestellt.","en":"【Although】 I had expressly ordered a direct flight to Mumbai, you issued me a flight with a stopover in Delhi.","rule":"OBWOHL = although, concession: Obwohl ich einen Direktflug bestellt hatte, haben Sie mir Tickets mit Zwischenstopp ausgestellt. Verb hatte at the end of the obwohl-clause, then the main clause starts with the verb (haben Sie).","od":["afterwards. An adverb; the verb would follow straight after it, but hatte is at the end.","although. Concession: Obwohl ich einen Direktflug bestellt hatte, …","namely, you see. A particle inside a sentence; it does not open a clause."]},{"x":"Tamara","no":15,"n":26,"a":"sondern","o":["besonders","sondern","sonst"],"de":"Der Flug war nicht nur anders als vereinbart, 【sondern】 auch noch viel teurer.","en":"The flight was not only different from what was agreed, 【but】 also much more expensive.","rule":"Nicht nur …, SONDERN auch …: after a negation (nicht nur) the correction is introduced with sondern. Besonders = especially, sonst = otherwise.","od":["especially. It does not fit nicht nur ….","but rather. nicht nur …, sondern auch.","otherwise. It gives an alternative or condition."]},{"x":"Grenzacker","no":19,"n":21,"a":"daher","o":["daher","denn","weil"],"de":"【daher】 schreibe ich Ihnen nun aus dem Skiparadies Obergurgl, wo ich jetzt mit einigen Freunden die Winterferien verbringe.","en":"【Therefore】 I am writing to you now from the ski paradise Obergurgl, where I am spending the winter holidays with some friends.","rule":"Daher = therefore, and the verb comes next (Daher schreibe ich …). Denn and weil give a reason and need a different word order (weil … schreibe ich: verb at the end).","od":["therefore. A result word: Daher schreibe ich Ihnen = that is why I write to you now. The verb comes right after it.","because (denn). It gives a reason and needs the subject first (denn ich schreibe), but here the verb follows the gap and the sentence states a consequence.","because (weil). It sends the verb to the end of the clause, but here \"schreibe\" follows the gap directly."]}]},{"key":"art","title":"Articles and relative pronouns","rule":"Gender, number and case must fit the noun. A relative pronoun takes gender and number from the noun before it and its case from its own clause (die Parkplätze, die … sind = Nominativ plural).","items":[{"x":"Petra","no":1,"n":25,"a":"den","o":["dem","den","der"],"de":"Bis spät abends höre ich nun täglich 【den】 Lärm der Restaurantsgäste im Garten.","en":"Until late in the evening I now hear 【the】 noise of the restaurant guests in the garden every day.","rule":"Hören takes an Akkusativ object. Lärm is masculine, so Akkusativ = den Lärm. Dem = Dativ masculine/neuter, der = Dativ feminine or Genitiv.","od":["the, Dativ masculine/neuter. Hören takes an Akkusativ object, so Dativ is wrong.","the, Akkusativ masculine. Hören + Akkusativ, and der Lärm is masculine: den Lärm.","the, Dativ/Genitiv feminine (also Nominativ masculine). Lärm is the object and masculine, so it needs the Akkusativ den."]},{"x":"Petra","no":1,"n":26,"a":"die","o":["denen","die","diese"],"de":"Die Parkplätze vor dem Haus, 【die】 eigentlich für die Mieter reserviert sind, sind immer besetzt.","en":"The parking spaces in front of the house, 【which】 are actually reserved for the tenants, are always taken.","rule":"Relative pronoun for die Parkplätze (plural). In the relative clause it is the subject of 'reserviert sind', so Nominativ plural = die. Denen would be Dativ plural (needs a Dativ verb or preposition), diese cannot introduce a relative clause.","od":["to which, Dativ plural. It needs a verb or preposition with Dativ in the relative clause, and \"reserviert sind\" has none.","which, Nominativ plural. It refers to die Parkplätze and is the subject of \"reserviert sind\".","these (demonstrative). It cannot open a relative clause that sends the verb to the end."]},{"x":"Eva","no":2,"n":29,"a":"der","o":["das","der","die"],"de":"Falls Sie noch Fragen haben oder sich wieder für ein Abonnement entscheiden, stehen wir Ihnen gerne unter 【der】 Nummer 0781/639 6259 von montags bis freitags von 8 bis 18 Uhr zur Verfügung.","en":"If you have more questions or decide on a subscription again, we are happy to be at your service on 【the】 number 0781/639 6259, Monday to Friday from 8 to 18.","rule":"Unter der Nummer: unter + Dativ, die Nummer is feminine, Dativ feminine = der. Fixed phrase for phone numbers (unter der Nummer erreichbar).","od":["the, neuter. Nummer is feminine, so das is wrong.","the, Dativ feminine. unter + Dativ: unter der Nummer (fixed phrase for phone numbers).","the, Nominativ/Akkusativ feminine. After unter here (a place) the Dativ der is needed."]},{"x":"Sophie","no":3,"n":27,"a":"die","o":["das","den","die"],"de":"Wir warten auf die neuen Möbel, 【die】 wir gekauft haben.","en":"We are waiting for the new furniture 【that】 we bought.","rule":"Relative pronoun: die Möbel, DIE wir gekauft haben. Möbel is plural; the relative pronoun is the Akkusativ object of gekauft: die (plural). Das / den are wrong gender or number.","od":["the/that, neuter singular. Möbel is plural, so das does not fit.","the, Akkusativ masculine singular. Möbel is plural, so den does not fit.","which, Akkusativ plural. The relative pronoun for die Möbel is the object of gekauft: die Möbel, die wir gekauft haben."]},{"x":"Andreas","no":6,"n":21,"a":"den","o":["das","den","der"],"de":"Ich hab dir doch schon vom Deutschkurs erzählt, 【den】 ich hier besuche.","en":"I have already told you about the German course 【that】 I am attending here.","rule":"Relative pronoun for der Deutschkurs: den (Akkusativ masculine, because ich besuche DEN KURS). Das / der do not match masculine Akkusativ.","od":["the/that, neuter. Deutschkurs is masculine.","the, Akkusativ masculine. The relative pronoun is the object of besuche: ich besuche den Kurs.","the, Nominativ masculine (or Dativ feminine). Kurs is the object, so the Akkusativ is needed."]},{"x":"Andreas","no":6,"n":29,"a":"die","o":["denen","deren","die"],"de":"Für Menschen, 【die】 ein paar Kilos zu viel haben, gibt es auch Tipps zum Abnehmen und Links zu verschiedenen Fitnesszentren in der Schweiz.","en":"For people 【who】 are a few kilos overweight there are also tips for losing weight and links to various fitness centres in Switzerland.","rule":"Relative pronoun for Menschen (plural), subject of 'haben': Nominativ plural = die. Denen = Dativ plural, deren = Genitiv plural.","od":["whom/which, Dativ plural. The relative pronoun is the subject of haben, so Nominativ is needed.","whose, Genitiv. It would mean \"people whose kilos\", which does not fit.","who, Nominativ plural. It is the subject of \"haben\": Menschen, die ein paar Kilos zu viel haben."]},{"x":"Sonja","no":9,"n":28,"a":"dem","o":["dem","den","denen"],"de":"Vielleicht kennst du auch jemanden, von 【dem】 ich Informationen über das Leben in Belgien bekommen kann?","en":"Perhaps you also know someone 【from whom】 I can get information about life in Belgium?","rule":"Relative pronoun after the preposition von: jemanden, von DEM. Von + Dativ, jemand is masculine singular, so Dativ masculine = dem. Denen would be plural, den Akkusativ.","od":["whom, Dativ masculine. von + Dativ, and jemand is masculine singular: von dem.","whom, Akkusativ masculine. After von the Dativ is needed.","whom, Dativ plural. jemanden is singular."]},{"x":"Carolina","no":10,"n":30,"a":"dem","o":["dem","den","der"],"de":"In Australien arbeiten wir meistens im Rahmen von Projekten und machen eigentlich alle Aufgaben auf 【dem】 Computer.","en":"In Australia we mostly work in projects and actually do all tasks on 【the】 computer.","rule":"Auf + Dativ: auf dem Computer (where? = on the computer). Computer is masculine, Dativ = dem. Den = Akkusativ (movement), der = feminine.","od":["the, Dativ masculine. auf + Dativ answers \"where?\": auf dem Computer.","the, Akkusativ masculine. It would mean movement onto the computer.","the, Dativ feminine. Computer is masculine."]},{"x":"Jennifer","no":12,"n":21,"a":"des","o":["den","der","des"],"de":"Radfahren macht hier nämlich viel Spaß trotz 【des】 Windes.","en":"Cycling is great fun here despite the 【wind】.","rule":"Trotz + Genitiv: trotz des Windes. Wind is masculine, Genitiv = des, the noun gets -es. Den / der do not fit the Genitiv masculine.","od":["the, Akkusativ masculine. trotz takes the Genitiv, not the Akkusativ.","the, Genitiv feminine/plural (or Dativ feminine). Wind is masculine.","the, Genitiv masculine. trotz + Genitiv: trotz des Windes (the noun gets -es)."]},{"x":"Thomas","no":14,"n":27,"a":"die","o":["den","der","die"],"de":"Statt der erwarteten 640 Euro kosteten 【die】 Tickets 720 Euro.","en":"Instead of the expected 640 euros, 【the】 tickets cost 720 euros.","rule":"Kosteten DIE Tickets 720 Euro: plural subject die Tickets (Nominativ plural). The verb kosteten (plural) agrees. Den / der do not fit Nominativ plural.","od":["the, Akkusativ masculine/Dativ plural. The subject is plural Nominativ.","the, Genitiv or Dativ feminine. It does not fit the plural subject.","the, Nominativ plural. Subject die Tickets, matching kosteten."]},{"x":"Tamara","no":15,"n":27,"a":"der","o":["der","deren","die"],"de":"Statt 【der】 erwarteten 640 Euro kostete der Flug 720 Euro.","en":"Instead of 【the】 expected 640 euros the flight cost 720 euros.","rule":"Statt DER erwarteten 640 Euro: statt + Genitiv plural. The article of the Genitiv plural is der (and the adjective ends in -en: erwarteten).","od":["the, Genitiv plural. statt + Genitiv: statt der erwarteten 640 Euro.","whose (Genitiv relative pronoun). It is not an article and needs a noun.","the, Nominativ/Akkusativ plural. statt needs the Genitiv."]},{"x":"Grenzacker","no":19,"n":30,"a":"einen","o":["ein","einem","einen"],"de":"Ich hoffe, dass auch Sie mit Ihrer Familie 【einen】 erholsamen Urlaub verbracht haben!","en":"I hope that you, too, have had 【a】 restful holiday with your family!","rule":"Accusative masculine: einen erholsamen Urlaub verbracht. Einem is dative, ein is nominative.","od":["a, Nominativ/Akkusativ neuter or Nominativ masculine (ein). Urlaub is masculine and the verb \"verbracht haben\" needs an Akkusativ, so this form does not fit.","a, Dativ (einem). There is no preposition or Dativ verb that asks for the Dativ.","a, Akkusativ masculine (einen). verbracht haben takes an Akkusativ object, and der Urlaub is masculine: einen erholsamen Urlaub."]}]},{"key":"pron","title":"Personal and reflexive pronouns","rule":"Find the person (ich, du, Sie …) and the case that the verb or the preposition needs: Akkusativ (mich, uns), Dativ (mir, ihnen) or the reflexive sich.","items":[{"x":"Petra","no":1,"n":30,"a":"man","o":["er","man","wir"],"de":"Vielleicht könnte 【man】 gemeinsam eine Lösung finden.","en":"Perhaps 【one】 could find a solution together.","rule":"Man = one, people in general: Vielleicht könnte man … finden (3rd person singular of the Konjunktiv II). Er would be one specific man who is not mentioned, wir would need könnten.","od":["he. It would mean one specific man who has not been mentioned.","one, people in general. Man + könnte (3rd person singular): perhaps one could find a solution together.","we. It would need könnten (wir könnten); könnte goes with er/sie/man."]},{"x":"Eva","no":2,"n":27,"a":"Sie","o":["Ihnen","sie","Sie"],"de":"Vielleicht gelingt es uns, 【Sie】 wieder von der Qualität von CHIP zu überzeugen.","en":"Perhaps we will manage to convince 【you】 again of the quality of CHIP.","rule":"Überzeugen takes the Akkusativ: uns gelingt es, SIE zu überzeugen (formal Sie = Akkusativ). Ihnen = Dativ, sie = she / they.","od":["to you (Dativ). überzeugen takes the Akkusativ, not the Dativ.","she/they (lower case). It does not mean the formal \"you\" and refers to someone else.","you, formal Akkusativ. jemanden überzeugen: uns gelingt es, Sie zu überzeugen."]},{"x":"Sophie","no":3,"n":22,"a":"uns","o":["ihnen","sich","uns"],"de":"Zwar ist immer noch nicht alles so eingerichtet, wie wir 【uns】 das wünschen.","en":"Admittedly not everything is furnished yet as we 【ourselves】 would like it.","rule":"Sich (Dativ) etwas wünschen: wie wir UNS das wünschen. The reflexive pronoun agrees with the subject wir: uns. Ihnen / sich do not match the person.","od":["to them. This is third person plural, but the subject is wir.","himself/herself/themselves. This reflexive pronoun is for er, sie, es, sie, Sie, not for wir.","ourselves, Dativ. The reflexive pronoun agrees with wir: wie wir uns das wünschen."]},{"x":"Nicole","no":5,"n":23,"a":"Ihnen","o":["euch","Ihnen","Sie"],"de":"Vielleicht liegt das an uns, weil wir 【Ihnen】 nicht das richtige Angebot gemacht haben.","en":"Perhaps that is down to us, because we did not make 【you】 the right offer.","rule":"Machen takes a Dativ person: wir haben IHNEN ein Angebot gemacht (Dativ of Sie). Sie would be Akkusativ, euch = Dativ/Akkusativ of ihr (informal).","od":["you (ihr, informal). The letter is formal, so Ihnen is needed.","to you (Dativ, formal). jemandem ein Angebot machen: das Angebot goes to Ihnen.","you (Akkusativ, formal). The person who gets the offer is the Dativ object, so Sie is wrong."]},{"x":"Nicole","no":5,"n":29,"a":"uns","o":["mich","sich","uns"],"de":"Wir freuen 【uns】 auf Sie!","en":"We look forward 【to】 seeing you!","rule":"Sich freuen auf + Akkusativ: the reflexive pronoun agrees with the subject wir: uns. Mich / sich do not fit the person.","od":["myself. The reflexive pronoun for ich; the subject is wir.","himself/herself/themselves. The reflexive pronoun for er, sie, es, sie; not for wir.","ourselves. sich freuen auf; the reflexive pronoun agrees with wir: wir freuen uns."]},{"x":"Andreas","no":6,"n":27,"a":"sich","o":["mir","dir","sich"],"de":"Außerdem kann man 【sich】 seinen persönlichen Speiseplan selbst erstellen und dafür passende Rezepte finden.","en":"You can also 【put together】 your personal menu yourself and find suitable recipes for it.","rule":"Sich (Dativ) etwas erstellen: man kann SICH seinen Speiseplan erstellen. Man takes the reflexive pronoun sich. Mir / dir belong to ich / du.","od":["to me. The reflexive pronoun for ich is not used with man.","to you. The reflexive pronoun for du is not used with man.","for oneself. Man takes the reflexive pronoun sich: man kann sich etwas erstellen."]},{"x":"Sonja","no":9,"n":22,"a":"dir","o":["dich","dir","Du"],"de":"Es ist nämlich etwas ganz Besonderes geschehen: Stell 【dir】 vor, ich habe die Stelle bei der EU in Brüssel bekommen!","en":"It is something quite special that has happened: imagine 【to yourself】, I got the job at the EU in Brussels!","rule":"Stell DIR vor! Sich (Dativ) etwas vorstellen: the Dativ pronoun of du is dir. Dich would be Akkusativ.","od":["yourself, Akkusativ. sich (Dativ) etwas vorstellen needs the Dativ.","to yourself, Dativ. Stell dir vor! is the Dativ of du.","you, Nominativ. The pronoun is the object here, not the subject."]},{"x":"Sonja","no":9,"n":25,"a":"man","o":["er","ich","man"],"de":"Aber ein bisschen Glück braucht 【man】 auch, damit so etwas gelingt.","en":"But 【one】 also needs a bit of luck so that something like this works out.","rule":"MAN braucht Glück = one needs luck (general, no specific person). Man + 3rd person singular verb braucht. Er / ich would not fit.","od":["he. It would mean a specific man who is not mentioned.","I. The verb would have to be brauche, not braucht.","one, people in general. Man + braucht (3rd person singular): one needs a bit of luck too."]},{"x":"Vera","no":11,"n":24,"a":"mir","o":["ihr","mich","mir"],"de":"Eine Freundin hat 【mir】 dann ein Zimmer in ihrer Wohngemeinschaft angeboten.","en":"A friend then offered 【me】 a room in her shared flat.","rule":"Anbieten takes the Dativ: eine Freundin hat MIR ein Zimmer angeboten. Mir = Dativ of ich. Mich would be Akkusativ.","od":["to her. eine Freundin is the subject; the person who gets the room is the writer.","me, Akkusativ. anbieten needs the Dativ for the person.","to me, Dativ. Eine Freundin hat mir ein Zimmer angeboten."]},{"x":"Jennifer","no":12,"n":22,"a":"mich","o":["mein","mich","mir"],"de":"Und es gibt auch Angebote für Radfahrer wie 【mich】, die sich vor allem erholen und nicht besonders anstrengen wollen.","en":"And there are also offers for cyclists like 【me】 who above all want to relax and not make a special effort.","rule":"Für Radfahrer WIE MICH: after wie the noun/pronoun takes the same case as the word it compares (Radfahrer in the Akkusativ after für): mich = Akkusativ of ich.","od":["my. It is a possessive, not a pronoun to put after wie.","me, Akkusativ. Radfahrer wie mich: after wie the pronoun takes the case of the word it is compared with (Radfahrer, Akkusativ after für).","me, Dativ. There is no Dativ verb or preposition here."]},{"x":"Thomas","no":14,"n":21,"a":"Ihnen","o":["ihnen","Ihnen","Sie"],"de":"Im Mai habe ich bei 【Ihnen】 für mich und meine Familie Flugtickets nach Indien bestellt und diese zwei Tage vor Abflug am 27.","en":"In May I ordered plane tickets to India for myself and my family from 【you】 and received them two days before departure on 27 June.","rule":"Bestellen bei + Dativ: ich habe bei IHNEN bestellt (formal Dativ of Sie). Sie would be Akkusativ, ihnen = to them (not formal).","od":["to them (lower case). It is not the formal form; the letter is to one person.","you, formal Dativ. bei + Dativ: bei Ihnen bestellt.","you, formal Akkusativ. bei needs the Dativ."]},{"x":"Thomas","no":14,"n":30,"a":"mir","o":["mich","mir","sich"],"de":"Ich bitte Sie, die Angelegenheit bald zu klären und 【mir】 dann zu antworten.","en":"I ask you to clear up the matter soon and to answer 【me】 then.","rule":"Antworten takes the Dativ: und MIR dann antworten. Mir = Dativ of ich. Mich = Akkusativ, sich does not match the person.","od":["me, Akkusativ. antworten needs the Dativ.","to me, Dativ. antworten + Dativ: mir dann antworten.","himself/herself. The reflexive pronoun does not match ich."]},{"x":"Tamara","no":15,"n":21,"a":"Ihnen","o":["ihnen","Ihnen","Sie"],"de":"Im Januar hatte ich bei 【Ihnen】 für mich und meine Familie einen Flug nach Indien gebucht.","en":"In January I booked a flight to India for myself and my family with 【you】.","rule":"Bestellen / buchen bei + Dativ: ich habe bei IHNEN gebucht (formal Dativ of Sie). Sie would be Akkusativ, ihnen is not formal.","od":["to them (lower case). It is not the formal form; the letter is to one person.","you, formal Dativ. bei + Dativ: bei Ihnen bestellt.","you, formal Akkusativ. bei needs the Dativ."]},{"x":"Viktor","no":17,"n":22,"a":"dir","o":["dich","dir","Du"],"de":"Es ist nämlich etwas ganz Besonderes geschehen: Stelle 【dir】 vor, ich habe die Stelle bei der EU in Brüssel bekommen!","en":"It is something quite special that has happened: imagine 【to yourself】, I got the job at the EU in Brussels!","rule":"Stell DIR vor! Sich (Dativ) etwas vorstellen: the Dativ pronoun of du is dir. Dich would be Akkusativ.","od":["yourself, Akkusativ. sich (Dativ) etwas vorstellen needs the Dativ.","to yourself, Dativ. Stell dir vor! is the Dativ of du.","you, Nominativ. The pronoun is the object here, not the subject."]},{"x":"Grenzacker","no":19,"n":28,"a":"mir","o":["meiner","mich","mir"],"de":"Im Notfall müssten Sie 【mir】 eine SMS oder eine E-Mail schicken.","en":"In an emergency you would have to send 【me】 a text message or an e-mail.","rule":"schicken takes a Dativ person: Sie müssten mir eine SMS schicken. Mich is accusative, meiner is genitive.","od":["of me, Genitiv/Dativ feminine (meiner). It is not the form for a person who receives something.","me, Akkusativ (mich). The Akkusativ object is the SMS; the person who receives it is Dativ.","me, Dativ (mir). Sie müssten mir eine SMS schicken: schicken takes the person in the Dativ."]}]},{"key":"qw","title":"Question words and da-words","rule":"Question words (wie, wann, welche, was) must fit the noun or verb; da-words (daran, darauf, davon) repeat the preposition of the verb: sich freuen auf → darauf, sich gewöhnen an → daran.","items":[{"x":"Sophie","no":3,"n":26,"a":"daran","o":["daran","darüber","davon"],"de":"Meinem Mann hat das am Anfang gar nicht gefallen, aber jetzt hat er sich 【daran】 gewöhnt.","en":"My husband did not like it at all at first, but now he has got used 【to】 it.","rule":"Sich an etwas gewöhnen: fixed pair gewöhnen + AN. The pronominal adverb daran replaces 'an die Farben'. Darüber (über) and davon (von) belong to other verbs.","od":["of it (da + an). sich gewöhnen AN is a fixed pair; daran replaces \"an die Farben\".","about it (da + über). über belongs to verbs like sich ärgern über, not gewöhnen.","of it (da + von). von belongs to verbs like sprechen von, not gewöhnen."]},{"x":"Andreas","no":6,"n":26,"a":"welche","o":["welche","welchen","welcher"],"de":"Fachleute beschreiben hier genau, 【welche】 Lebensmittel für unseren Körper wichtig und gesund sind und wie oft und wie viel man pro Tag essen sollte.","en":"Experts describe here exactly 【which】 foods are important and healthy for our body and how often and how much one should eat per day.","rule":"Indirect question: genau beschreiben, WELCHE Lebensmittel wichtig sind. Welche + plural noun (Nominativ plural, subject of sind). Welchen = Dativ plural / Akkusativ masculine, welcher = Nominativ masculine.","od":["which, Nominativ plural. Indirect question: welche Lebensmittel … wichtig sind; Lebensmittel is the plural subject.","which, Dativ plural or Akkusativ masculine. Neither case fits the subject of sind.","which, Nominativ masculine or Dativ feminine. Lebensmittel is plural."]},{"x":"Iris","no":8,"n":22,"a":"darauf","o":["darauf","darum","dazu"],"de":"Ich freue mich schon sehr 【darauf】, denn schließlich haben wir uns fast ein halbes Jahr nicht gesehen.","en":"I am already very much looking forward 【to it】, because after all we have not seen each other for almost half a year.","rule":"Sich freuen auf: ich freue mich schon sehr DARAUF (da + r + auf), replacing 'auf den Besuch'. Darum (um), dazu (zu) belong to other verbs.","od":["about it (da + r + auf). sich freuen AUF; darauf replaces \"auf den Besuch\".","about it (da + r + um). It belongs to verbs with um (bitten um, sich kümmern um).","about it (da + zu). It belongs to verbs with zu (gehören zu, passen zu)."]},{"x":"Vera","no":11,"n":27,"a":"daran","o":["daran","darauf","darüber"],"de":"Ich staune selbst über meine Noten, wenn ich 【daran】 denke, wie wenig Zeit ich mir für Hausaufgaben nehme.","en":"I am surprised myself at my marks when I 【think about it】 and how little time I take for homework.","rule":"Denken AN + Akkusativ: fixed pair. Wenn ich DARAN denke = when I think about it (da + r + an). Darauf (auf) and darüber (über) belong to other verbs.","od":["of it (da + an). denken AN is a fixed pair: wenn ich daran denke.","on it (da + r + auf). It belongs to verbs like warten auf.","about it (da + r + über). It belongs to verbs like sprechen über."]},{"x":"Tamara","no":15,"n":22,"a":"was","o":["das","was","wie"],"de":"Leider entsprach unser Flug überhaupt nicht dem, 【was】 bei der Buchung am Telefon ausgemacht worden war.","en":"Unfortunately our flight did not correspond at all to 【what】 had been agreed when booking by telephone.","rule":"Dem, WAS … = that which: after a demonstrative (dem) the relative pronoun was refers to a whole thing (nicht dem, was ausgemacht worden war). Das / wie do not fit the relative clause.","od":["that/the. After dem a relative pronoun is needed; das does not fit here.","what, which. Relative pronoun after dem: dem, was … = that which.","how, as. It is a comparison word, not a relative pronoun."]},{"x":"Rita","no":18,"n":21,"a":"davon","o":["dafür","damit","davon"],"de":"Wie versprochen möchte ich dir gleich 【davon】 erzählen.","en":"As promised I would like to tell you straight away 【about it】.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["for it (da + für). erzählen takes von, not für.","with it (da + mit). erzählen takes von, not mit.","about it (da + von). erzählen von: I want to tell you about it."]},{"x":"Grenzacker","no":19,"n":22,"a":"wo","o":["wo","woher","wohin"],"de":"Daher schreibe ich Ihnen nun aus dem Skiparadies Obergurgl, 【wo】 ich jetzt mit einigen Freunden die Winterferien verbringe.","en":"Therefore I am writing to you now from the ski paradise Obergurgl, 【where】 I am spending the winter holidays with some friends.","rule":"Wo = where: a place (Obergurgl, wo ich Winterferien verbringe). Woher = from where, wohin = to where (movement).","od":["where. A place word for Obergurgl: Skiparadies Obergurgl, wo ich Winterferien verbringe.","from where (woher). It asks for the origin, but the writer is in Obergurgl now.","to where (wohin). It needs a movement (wohin fahren), but the writer is already there."]},{"x":"Grenzacker","no":19,"n":24,"a":"wie","o":["als","wie","wo"],"de":"Im Skikurs mache ich langsam Fortschritte, aber es ist gar nicht so einfach, 【wie】 es aussieht.","en":"In the ski course I am slowly making progress, but it is not as easy 【as】 it looks.","rule":"nicht so einfach, wie es aussieht = not as easy as it looks. so … wie compares; als is for after a comparative (einfacher als).","od":["than (als). It stands after a comparative (einfacher als). Here the text has \"so einfach\", which needs wie.","as, like (wie). so einfach, wie es aussieht = as easy as it looks.","where (wo). It is a place word, but there is no place here."]}]},{"key":"verb","title":"Verb forms","rule":"Look at the subject (person), the tense and the bracket: haben / sein + Partizip II at the end (Perfekt), Konjunktiv II (wäre, würde, hätte) for polite or unreal, an infinitive after a modal verb or werden, the verb at the end after weil / dass.","items":[{"x":"Petra","no":1,"n":22,"a":"war","o":["war","wäre","würde"],"de":"Ich 【war】 die ganze Zeit sehr zufrieden, denn im Haus war es immer ruhig, sauber und sicher.","en":"I 【was】 very satisfied the whole time, because it was always quiet, clean and safe in the building.","rule":"War is the Präteritum of sein: the writer reports a real fact in the past (ich war die ganze Zeit zufrieden). Wäre / würde are Konjunktiv II (unreal) and do not fit a real experience.","od":["was (Präteritum of sein). The writer reports a real, finished fact in the past: I was satisfied the whole time.","would be (Konjunktiv II). That is for unreal or polite things, but this is something that really was the case.","would (Konjunktiv II helper). It needs an infinitive at the end (würde zufrieden sein), so it cannot stand alone here."]},{"x":"Petra","no":1,"n":23,"a":"hat","o":["hat","ist","wurde"],"de":"In der Zwischenzeit 【hat】 sich die Wohnqualität durch die Eröffnung des Restaurants im Erdgeschoss aber deutlich verschlechtert.","en":"In the meantime, however, the quality of living 【has】 clearly got worse because of the opening of the restaurant on the ground floor.","rule":"Sich verschlechtern is a reflexive verb and forms the Perfekt with haben: sich hat verschlechtert. The participle verschlechtert at the end of the sentence confirms the Perfekt. Ist / wurde need other participles (ist gekommen, wurde verschlechtert = passive).","od":["has (haben + Partizip II). Sich verschlechtern is reflexive and forms the Perfekt with haben: hat sich verschlechtert.","is (sein + Partizip II). The sein-Perfekt is for movement or a change of place (ist gegangen); verschlechtern uses haben.","became (Präteritum of werden). It would make a passive, but sich verschlechtert is not passive and the sentence is in the Perfekt."]},{"x":"Petra","no":1,"n":28,"a":"geöffnet","o":["geöffnet","öffnen","öffnet"],"de":"Außerdem fühle ich mich im Haus nicht mehr sicher, weil das Restaurant oft die ganze Nacht 【geöffnet】 hat.","en":"Besides, I no longer feel safe in the building, because the restaurant is often 【open】 all night.","rule":"Perfekt with haben: das Restaurant hat geöffnet. In the weil-clause the verb hat is last and the participle geöffnet stands before it. Öffnen = infinitive, öffnet = present, neither can stand before hat.","od":["opened (Partizip II). hat geöffnet is the Perfekt; the participle stands before hat at the end of the weil-clause.","to open (infinitive). It needs a modal verb (kann öffnen), not hat.","opens (present, er/sie/es). It would be a second finite verb next to hat."]},{"x":"Eva","no":2,"n":22,"a":"möchten","o":["möchte","möchten","möchtest"],"de":"Schade, dass Sie CHIP nicht weiter beziehen 【möchten】.","en":"We are sorry that you 【want】 to stop receiving CHIP.","rule":"The subject is Sie (formal you): the modal verb must agree: Sie möchten (plural). Möchte = ich / er, möchtest = du. The modal verb is the last word of the dass-clause.","od":["I/he/she would like (ich, er/sie/es form). The subject is Sie, so this form does not agree.","would like (Sie, plural form). Formal Sie takes the plural ending; it is the last word of the dass-clause.","you would like (du form). That is informal \"you\", but the letter uses formal Sie."]},{"x":"Eva","no":2,"n":25,"a":"verlieren","o":["verlieren","verliert","verloren"],"de":"Wir 【verlieren】 Sie natürlich nur ungern als Abonnenten und würden uns freuen, wenn Sie CHIP trotzdem ab und zu am Kiosk kaufen.","en":"Of course we 【lose】 you as a subscriber only reluctantly and would be pleased if you still bought CHIP at the kiosk now and then.","rule":"The subject is wir: verlieren (wir / Sie / sie plural). Verliert = er / sie / es, verloren is the participle and needs haben.","od":["lose (wir, Sie, sie plural). The subject is wir, so the infinitive form fits.","loses (er/sie/es). The subject is wir, so the verb must be plural.","lost (Partizip II). It needs a helper verb (haben verloren), and there is none."]},{"x":"Sophie","no":3,"n":23,"a":"dauern","o":["dauern","dauert","gedauert"],"de":"Aber wir wussten, dass das einige Zeit 【dauern】 würde, bis alles fertig ist.","en":"But we knew that it would 【take】 some time until everything is finished.","rule":"Dass das einige Zeit dauern WÜRDE: the würde-form ends with the infinitive dauern. Dauert = present, gedauert needs a helper verb (hat gedauert).","od":["to last (infinitive). würde + infinitive at the end: dass das einige Zeit dauern würde.","lasts (present). würde is already the finite verb, so a second finite verb cannot follow.","lasted (Partizip II). It would need a helper (hat gedauert), and würde + Partizip II is not correct."]},{"x":"Sophie","no":3,"n":24,"a":"aussuchen","o":["ausgesucht","aussuchen","aussuchten"],"de":"Unsere beiden Kinder durften sich die Farben für die Wände selbst 【aussuchen】 Sie haben sich für Blau und Gelb entschieden.","en":"Our two children were allowed to 【choose】 the colours for the walls themselves.","rule":"Modal verb + infinitive at the end: Die Kinder durften die Farben aussuchen. After a modal verb the infinitive stands at the end; ausgesucht (participle) would need haben, aussuchten would be a wrong Präteritum.","od":["chosen (Partizip II). It would need haben, but durften is already the finite verb.","to choose (infinitive). Modal verb + infinitive at the end: durften … aussuchen.","chose (Präteritum). That is a second finite verb after the modal durften, which is not allowed."]},{"x":"Sophie","no":3,"n":25,"a":"hat","o":["hat","ist","wird"],"de":"Meinem Mann 【hat】 das am Anfang gar nicht gefallen, aber jetzt hat er sich daran gewöhnt.","en":"My husband did not like it at all at first, but now he has 【got】 used to it.","rule":"Gefallen takes the Dativ (meinem Mann hat das nicht gefallen) and forms the Perfekt with haben. Ist / wird do not match the participle gefallen.","od":["has (haben + Partizip II). gefallen forms the Perfekt with haben, and takes the Dativ: meinem Mann hat das nicht gefallen.","is (sein + Partizip II). gefallen does not use sein.","becomes (werden). wird + gefallen would be a different tense; the sentence is in the past (am Anfang)."]},{"x":"Sophie","no":3,"n":29,"a":"würden","o":["worden","wurden","würden"],"de":"Wir würden uns alle sehr freuen, wenn Sie und Ihr Mann uns sehr bald besuchen 【würden】.","en":"We would all be very pleased if you and your husband would 【visit】 us very soon.","rule":"Wenn Sie uns besuchen WÜRDEN: wenn + Konjunktiv II for a wish (würden + infinitive besuchen). Wurden / worden are forms of the passive and do not fit.","od":["been (Partizip II of passive werden). It only appears with sein (ist besucht worden) and cannot stand here.","became/were (Präteritum of werden). It is not Konjunktiv II, so it does not express a wish after wenn.","would (Konjunktiv II). wenn + würden + infinitive expresses a wish: wenn Sie uns besuchen würden."]},{"x":"Nicole","no":5,"n":22,"a":"sind","o":["seid","sein","sind"],"de":"Schade, dass Sie bisher noch nicht Kunde bei Kaffee Partner 【sind】.","en":"We are sorry that you 【are】 not yet a customer of Kaffee Partner.","rule":"Subject Sie (formal): the verb is sind (Sie sind). Seid = ihr, sein is the infinitive. It is the last word of the dass-clause: dass Sie noch nicht Kunde SIND.","od":["are (ihr form, informal). The subject is formal Sie.","to be (infinitive). A dass-clause needs a finite verb.","are (Sie sind). Formal Sie takes sind; it is the last word of the dass-clause."]},{"x":"Nicole","no":5,"n":24,"a":"kennen gelernt","o":["kennen gelernt","kennen lernen","kennen lernte"],"de":"Das richtige Angebot haben wir nicht gemacht, seit wir uns vor einiger Zeit in Köln auf der ANUGA 【kennen gelernt】 haben.","en":"We have not made the right offer since we 【met】 some time ago in Cologne at ANUGA.","rule":"Perfekt in the weil/seit-clause: seit wir uns kennen gelernt HABEN. The participle kennen gelernt stands before the helper verb haben at the end. Kennen lernen (infinitive) and kennen lernte (Präteritum) do not fit.","od":["met (Partizip II). Perfekt seit wir uns kennen gelernt haben: the participle stands before haben at the end.","to get to know (infinitive). It would need a modal verb or zu, not haben.","got to know (Präteritum). A finite verb cannot stand before haben at the end."]},{"x":"Nicole","no":5,"n":25,"a":"möchten","o":["mochten","möchten","mögen"],"de":"Wir 【möchten】 das jetzt mit dem aktuellen Katalog nachholen, den Sie heute erhalten.","en":"We 【want】 to make up for that now with the current catalogue that you receive today.","rule":"Wir MÖCHTEN: 1st person plural of möchten + infinitive nachholen at the end. Mochten is the Präteritum of mögen, mögen has another meaning (to like).","od":["liked (Präteritum of mögen). The sentence is present and means a wish, not a past liking.","would like (wir). A polite wish, with the infinitive nachholen at the end.","to like, like (wir mögen). It has another meaning (to like things), not the wish \"to make up for it\"."]},{"x":"Nicole","no":5,"n":26,"a":"finden","o":["fanden","finden","findet"],"de":"Sie 【finden】 darin viele nützliche und attraktive Dinge rund um das Thema Kaffee und Trinkwasser für Mitarbeiter und Besucher.","en":"In it you 【will find】 many useful and attractive things around the subject of coffee and drinking water for employees and visitors.","rule":"Sie FINDEN darin …: the subject is Sie (formal) = 3rd person plural verb form finden. Fanden = Präteritum, findet = er / sie / es.","od":["found (Präteritum). The text is in the present.","find (Sie, plural form). Formal Sie takes the plural verb form.","finds (er/sie/es). The subject is formal Sie, not a single he/she/it."]},{"x":"Nicole","no":5,"n":28,"a":"zeigt","o":["gezeigt","zeigen","zeigt"],"de":"Aber auch Tee, kleine Leckereien und nette Kalender für Büro und Zuhause 【zeigt】 Ihnen unser Geschenkkatalog.","en":"But our gift catalogue also 【shows】 you tea, small treats and nice calendars for the office and home.","rule":"The subject is the singular noun unser Geschenkkatalog: 3rd person singular zeigt. Gezeigt is a participle, zeigen = infinitive/plural.","od":["shown (Partizip II). It needs a helper verb, and none is there.","to show, show (plural). The subject Geschenkkatalog is singular.","shows (er/sie/es). The singular subject unser Geschenkkatalog needs zeigt."]},{"x":"Andreas","no":6,"n":24,"a":"konnte","o":["können","könnten","konnte"],"de":"Die interessanteste Internetseite, die ich finden 【konnte】, ist www.gesund.ch.","en":"The most interesting website that I 【could】 find is www.gesund.ch.","rule":"Relative clause: die Internetseite, die ich finden KONNTE. In the past the modal is in the Präteritum: konnte (ich). The verb stands at the end of the relative clause.","od":["can (infinitive/wir, Sie, sie). The subject is ich and the verb is past.","could (Konjunktiv II, plural). It would be \"would be able to\", and the subject ich needs the singular.","could (ich konnte). Past of können; the verb stands at the end of the relative clause."]},{"x":"Andreas","no":6,"n":28,"a":"finden","o":["fand","finden","gefunden"],"de":"Außerdem kann man sich seinen persönlichen Speiseplan selbst erstellen und dafür passende Rezepte 【finden】.","en":"You can also put together your personal menu yourself and 【find】 suitable recipes for it.","rule":"Man kann … erstellen und … FINDEN: after the modal kann both verbs are infinitives. Fand = Präteritum, gefunden = participle.","od":["found (Präteritum). A finite verb cannot follow kann as the second verb.","to find (infinitive). After kann both verbs are infinitives: erstellen und finden.","found (Partizip II). It would need a helper verb (haben gefunden)."]},{"x":"Andreas","no":6,"n":30,"a":"Schreibe","o":["Schreibe","Schreiben","Schreibt"],"de":"【Schreibe】 mir doch möglichst bald zurück!","en":"【Write】 back to me as soon as possible!","rule":"Imperative (command) to a friend, du-form: Schreibe mir bald! The verb comes first. Schreibt = ihr, Schreiben = infinitive / Sie-form.","od":["write (du imperative). Schreibe mir bald! Speaking to one friend; the verb comes first.","to write / write (Sie). It would need \"Sie\" after it (Schreiben Sie!).","write (ihr imperative). That is for several people, but the letter is to one friend."]},{"x":"Iris","no":8,"n":25,"a":"wäre","o":["hätte","wäre","würde"],"de":"Mal wieder eine ganze Nacht tanzen, das 【wäre】 mein Traum!","en":"To dance a whole night again – that 【would be】 my dream!","rule":"Das WÄRE mein Traum: Konjunktiv II of sein for an unreal wish. Hätte (haben) and würde (needs an infinitive) do not fit.","od":["would have (Konjunktiv II of haben). \"ein Traum haben\" does not fit; the dream is something that would be.","would be (Konjunktiv II of sein). Das wäre mein Traum = an unreal wish.","would. It needs an infinitive at the end (würde sein), so it cannot stand alone here."]},{"x":"Iris","no":8,"n":29,"a":"will","o":["darf","soll","will"],"de":"Jedenfalls 【will】 ich versuchen, eine Mitfahrgelegenheit zu finden.","en":"In any case I 【want to】 try to find a lift.","rule":"Ich WILL versuchen = I want to try. Subject ich: will (1st person of wollen) + infinitive versuchen with zu. Darf = allowed, soll = should: the meaning differs.","od":["may, be allowed to. It is about permission.","should, be supposed to. It is an order or expectation from someone else.","want to. Ich will versuchen = I want to try, the writer's own intention."]},{"x":"Sonja","no":9,"n":21,"a":"geschehen","o":["geschah","geschehen","geschieht"],"de":"Es ist nämlich etwas ganz Besonderes 【geschehen】: Stell dir vor, ich habe die Stelle bei der EU in Brüssel bekommen!","en":"It is something quite special that has 【happened】: imagine to yourself, I got the job at the EU in Brussels!","rule":"Perfekt of geschehen: es ist … geschehen. Geschehen uses sein as the helper (ist). The participle stands at the end. Geschah = Präteritum, geschieht = present.","od":["happened (Präteritum). After ist the Partizip II is needed, not a finite verb.","happened (Partizip II). es ist etwas Besonderes geschehen: Perfekt of geschehen with sein.","happens (present). It would be a second finite verb next to ist."]},{"x":"Sonja","no":9,"n":23,"a":"wurden","o":["halten","wären","wurden"],"de":"Du weißt noch: Es gab ungefähr 300 Bewerber, und unter denen 【wurden】 die besten ausgesucht.","en":"You still remember: there were about 300 applicants, and among them the best 【were】 chosen.","rule":"Passive in the past: unter ihnen WURDEN die besten ausgesucht = the best ones were chosen. Plural subject die besten: wurden + participle ausgesucht.","od":["to hold. It is not a form of werden and does not fit.","would be (Konjunktiv II of sein). It describes an unreal state, not the real selection.","were (Präteritum of werden). Passive: wurden … ausgesucht = were chosen."]},{"x":"Sonja","no":9,"n":29,"a":"treffen","o":["getroffen","treffe","treffen"],"de":"Ich würde dich am liebsten kurz 【treffen】, um mit dir persönlich zu sprechen.","en":"I would most like to 【meet】 you briefly to speak with you in person.","rule":"Ich würde dich … TREFFEN: würde + infinitive (treffen), the infinitive stands at the end. Getroffen / treffe do not fit after würde.","od":["met (Partizip II). After würde the infinitive is needed, not a participle.","meet (ich, present). würde is already the finite verb.","to meet (infinitive). würde + infinitive at the end: ich würde dich treffen."]},{"x":"Carolina","no":10,"n":21,"a":"erzählt","o":["erzähle","erzählen","erzählt"],"de":"Seit ich dir letzte Mal von meinem Sprachaufenthalt in der Schweiz 【erzählt】 habe, ist viel passiert.","en":"Since I last 【told】 you about my language stay in Switzerland, a lot has happened.","rule":"Perfekt: seit ich dir erzählt HABE. The participle erzählt stands before the helper verb habe at the end of the subordinate clause.","od":["tell (ich, present). It would be a second finite verb; the Perfekt needs habe + participle.","to tell (infinitive). A Perfekt needs a participle.","told (Partizip II). seit ich dir erzählt habe: the participle stands before habe at the end."]},{"x":"Carolina","no":10,"n":29,"a":"müssen","o":["brauchen","haben","müssen"],"de":"Zwischen der Schule hier und unserem Schulsystem in Australien gibt es einige Unterschiede: In der Schweiz sprechen die Lehrer viel und die Schüler 【müssen】 Vieles im Kopf behalten oder aufschreiben.","en":"Between the school here and our school system in Australia there are some differences: in Switzerland the teachers talk a lot and the pupils 【have to】 remember a lot or write it down.","rule":"Die Schüler MÜSSEN vieles behalten = the pupils have to remember. Müssen + infinitive; the context is obligation in school. Haben would need zu, brauchen needs nicht / zu.","od":["need. It needs nicht or zu and does not mean obligation here.","have. It would need zu (haben zu behalten).","must, have to. Müssen + infinitive: the pupils have to remember a lot."]},{"x":"Jennifer","no":12,"n":25,"a":"beeindruckt","o":["beeindrucken","beeindruckend","beeindruckt"],"de":"Besonders 【beeindruckt】 hat mich aber die Stadt Burg auf Fehmarn.","en":"The town of Burg on Fehmarn 【impressed】 me especially, though.","rule":"Perfekt: Burg hat mich BEEINDRUCKT. The participle beeindruckt (beeindrucken). Beeindruckend would be an adjective ('impressive').","od":["to impress (infinitive). hat needs a participle.","impressive (adjective). It is not a participle after hat.","impressed (Partizip II). Perfekt: Burg hat mich beeindruckt."]},{"x":"Jennifer","no":12,"n":28,"a":"erlauben","o":["erlauben","erlaubt","erlaubte"],"de":"Außerdem gibt es Markierungen auf den Straßen, die den Radfahrern 【erlauben】, sich bei roten Ampeln vor die Autos zu stellen.","en":"Besides, there are markings on the streets that 【allow】 cyclists to stand in front of the cars at red lights.","rule":"Relative clause: Markierungen, die den Radfahrern ERLAUBEN, sich … zu stellen. The relative pronoun die refers to the plural Markierungen, so the verb is plural: erlauben. Erlaubt / erlaubte are singular. Erlauben takes the Dativ (den Radfahrern).","od":["allow (plural). die refers to the plural Markierungen, so the verb is plural.","allows (er/sie/es). It would fit a single subject.","allowed (Präteritum singular). Wrong number and wrong tense."]},{"x":"Jennifer","no":12,"n":30,"a":"mitzunehmen","o":["mitgenommen","mitnehmen","mitzunehmen"],"de":"Du siehst also: Es hat sich gelohnt, das Fahrrad 【mitzunehmen】.","en":"So you see: it was worth 【taking】 the bike along.","rule":"Es hat sich gelohnt, das Fahrrad MITZUNEHMEN: zu-infinitive of a separable verb: zu stands between the prefix and the verb (mit-zu-nehmen). Mitnehmen (without zu) and mitgenommen (participle) do not fit.","od":["taken along (Partizip II). After \"es hat sich gelohnt\" a zu-infinitive is needed, not a participle.","to take along (infinitive without zu). The structure needs zu.","to take along (zu-infinitive). With a separable verb zu goes between the prefix and the verb: mit-zu-nehmen."]},{"x":"Thomas","no":14,"n":22,"a":"war","o":["hat","war","wäre"],"de":"Leider entsprachen die Tickets überhaupt nicht dem, was zuvor bei der Buchung am Telefon ausgemacht worden 【war】.","en":"Unfortunately the tickets did not correspond at all to what had 【been】 agreed beforehand when booking by telephone.","rule":"Plusquamperfekt passive: was zuvor ausgemacht worden WAR. The helper war stands at the end after the participle worden. Hat / wäre do not fit the passive in the past perfect.","od":["has. It does not fit a passive in the past perfect.","was. ausgemacht worden war: passive in the past perfect; the helper stands at the end.","would be (Konjunktiv II). It says a real earlier agreement, not an unreal one."]},{"x":"Viktor","no":17,"n":21,"a":"geschehen","o":["geschah","geschehen","geschieht"],"de":"Es ist nämlich etwas ganz Besonderes 【geschehen】: Stelle dir vor, ich habe die Stelle bei der EU in Brüssel bekommen!","en":"It is something quite special that has 【happened】: imagine to yourself, I got the job at the EU in Brussels!","rule":"Perfekt of geschehen: es ist … geschehen. Geschehen uses sein as the helper (ist). The participle stands at the end. Geschah = Präteritum, geschieht = present.","od":["happened (Präteritum). After ist the Partizip II is needed, not a finite verb.","happened (Partizip II). es ist etwas Besonderes geschehen: Perfekt of geschehen with sein.","happens (present). It would be a second finite verb next to ist."]},{"x":"Viktor","no":17,"n":25,"a":"hätte","o":["habe","hätte","würde"],"de":"Trotzdem – ohne meine Sprachkenntnisse und meine Auslandserfahrung 【hätte】 ich die Stelle sicher nicht bekommen.","en":"Even so – without my language skills and my experience abroad I 【would have】 certainly not got the job.","rule":"Ohne meine Sprachkenntnisse HÄTTE ich die Stelle nicht bekommen: unreal past condition (Konjunktiv II Plusquamperfekt): hätte + participle bekommen at the end. Habe (Perfekt, real) and würde do not fit.","od":["have (Perfekt). The sentence is an unreal condition, not a real fact.","would have (Konjunktiv II Plusquamperfekt). Ohne meine Sprachkenntnisse hätte ich die Stelle nicht bekommen: unreal condition about something past.","would. würde … bekommen would refer to the present or future; here the job was already won."]},{"x":"Rita","no":18,"n":22,"a":"war","o":["bin","habe","war"],"de":"Am Anfang 【war】 ich ziemlich enttäuscht, weil ich auf meine vielen Bewerbungsschreiben insgesamt nur zwei Antworten bekommen habe.","en":"At the beginning I 【was】 quite disappointed, because I had only received two answers to my many job applications.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["am (present of sein). Am Anfang points to the past, and the weil-clause is in the Perfekt.","have. It does not work with enttäuscht; this one needs sein.","was (Präteritum of sein). Am Anfang war ich enttäuscht."]},{"x":"Rita","no":18,"n":24,"a":"gepasst","o":["gepasst","passen","passt"],"de":"Aber zum Glück hat eine davon 【gepasst】: Ich werde nun zwei Nachmittage in der Woche als Babysitterin bei einer Familie arbeiten, die zwei Kinder hat.","en":"But luckily one of them 【worked out】: I will now work two afternoons a week as a babysitter for a family that has two children.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["fitted (Partizip II). Perfekt: hat eine davon gepasst.","to fit (infinitive). hat needs a participle.","fits (present). It would be a second finite verb after hat."]},{"x":"Rita","no":18,"n":30,"a":"geht","o":["geht","geht’s","ging"],"de":"Für heute wünsche ich dir alles Gute – schreibe mir bald, wie es dir 【geht】.","en":"For today I wish you all the best – write to me soon how you 【are doing】.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["goes. wie es dir geht = how you are; the verb goes to the end of the indirect question.","goes it (colloquial). It already contains \"es\", so it would double it.","went (Präteritum). The question is about now."]},{"x":"Grenzacker","no":19,"n":27,"a":"bin","o":["bin","werde","würde"],"de":"Allerdings 【bin】 ich telefonisch nur über Handy erreichbar.","en":"However, 【I am】 reachable by phone only via mobile.","rule":"Allerdings bin ich telefonisch nur über Handy erreichbar: ich + bin. Würde would need an infinitive at the end, werde is the future form.","od":["am (bin). Allerdings bin ich telefonisch nur über Handy erreichbar: ich + bin, and the adjective \"erreichbar\" completes the sentence.","will (werde). It needs an infinitive at the end (werde erreichbar sein), but the sentence ends with \"erreichbar\".","would (würde). It also needs an infinitive at the end (würde erreichbar sein)."]},{"x":"Grenzacker","no":19,"n":29,"a":"kennen","o":["kenne","kennen","kennt"],"de":"Meine Handynummer und E-Mail-Adresse 【kennen】 Sie ja.","en":"You 【know】 my mobile number and e-mail address.","rule":"Sie is the polite you: Sie kennen. Kenne = ich, kennt = er/sie/es.","od":["I know (kenne). The subject is the polite \"Sie\", so the verb must be the \"Sie\" form.","you know (kennen). Sie kennen: the polite you takes the plural form of the verb.","he/she/it knows, you (plural) know (kennt). It does not fit the polite \"Sie\"."]}]},{"key":"end","title":"Endings: adjectives, possessives, nouns","rule":"The ending depends on the case, gender and number of the noun: Dativ masculine / neuter -em, Akkusativ masculine -en, after a preposition check the case. Check the article before the gap.","items":[{"x":"Petra","no":1,"n":21,"a":"Ihrem","o":["Ihr","Ihrem","Ihren"],"de":"Wie Sie wissen, miete ich nun schon seit drei Jahren eine Wohnung in 【Ihrem】 Haus.","en":"As you know, I have been renting a flat in 【your】 building for three years now.","rule":"Ihrem Haus: in + Dativ (where? = in which house), Haus is neuter, so the Dativ article/possessive is -em: in dem Haus = in Ihrem Haus. Ihr = Nominativ/Akkusativ neuter, Ihren = Akkusativ masculine or Dativ plural.","od":["your, Nominativ/Akkusativ neuter. After in (a place, where?) the Dativ is needed, so Ihr does not fit.","your, Dativ neuter. in + Dativ answers \"where?\", and das Haus is neuter, so in dem Haus = in Ihrem Haus.","your, Akkusativ masculine or Dativ plural. Haus is neuter singular, so -en does not fit."]},{"x":"Petra","no":1,"n":29,"a":"Probleme","o":["Problem","Probleme","Problemen"],"de":"Ich möchte Sie dringend bitten, sich um diese 【Probleme】 zu kümmern und mit den Restaurantbesitzern zu sprechen.","en":"I urgently ask you to take care of these 【problems】 and to speak to the restaurant owners.","rule":"Sich um etwas kümmern: um + Akkusativ. Diese Probleme = Akkusativ plural, the noun has no ending (das Problem, die Probleme). Problemen would be Dativ plural.","od":["problem, singular. After diese the noun is plural; one problem would be dieses Problem.","problems, Akkusativ plural. um + Akkusativ, and the plural noun has no extra ending.","problems, Dativ plural (-n). um takes the Akkusativ, not the Dativ."]},{"x":"Eva","no":2,"n":23,"a":"nächsten","o":["nächste","nächsten","nächstes"],"de":"Die Belieferung beenden wir mit unserem 【nächsten】 Heft.","en":"We end the delivery with our 【next】 issue.","rule":"Mit unserem nächsten Heft: mit + Dativ, Heft is neuter. After unserem the adjective ends in -en (Dativ singular, mixed declension): nächsten.","od":["next, ending -e. This is Nominativ/Akkusativ; here mit needs the Dativ.","next, ending -en. mit + Dativ neuter (Heft): after unserem the adjective ends in -en.","next, ending -es. This is Nominativ/Akkusativ neuter and does not follow mit unserem."]},{"x":"Eva","no":2,"n":30,"a":"freundlichen","o":["freundlich","freundlichem","freundlichen"],"de":"Mit 【freundlichen】 Grüßen","en":"With 【kind】 regards","rule":"Mit freundlichen Grüßen: mit + Dativ plural. An adjective without article in the Dativ plural ends in -en: freundlichen. Fixed ending of formal letters.","od":["friendly, no ending. Without an ending it only works after sein (er ist freundlich).","friendly, Dativ singular masculine/neuter. Grüßen is plural, so -em does not fit.","friendly, Dativ plural. mit + Dativ plural: mit freundlichen Grüßen, the fixed closing of formal letters."]},{"x":"Sophie","no":3,"n":28,"a":"nächsten","o":["nächsten","nächster","nächstes"],"de":"In der 【nächsten】 Woche kommen sie endlich.","en":"They are finally coming in the 【next】 week.","rule":"In der nächsten Woche: in + Dativ, Woche is feminine: in der. After der the adjective in the Dativ singular ends in -en: nächsten.","od":["next, ending -en. in der + Dativ feminine (Woche): after der the adjective ends in -en.","next, ending -er. This ending is for adjectives without a preceding article; here der stands in front.","next, ending -es. This is Nominativ/Akkusativ neuter; Woche is feminine."]},{"x":"Sophie","no":3,"n":30,"a":"unserer","o":["unser","unserer","unseres"],"de":"Und trotz 【unserer】 schönen neuen Wohnung sind wir ein bisschen traurig, dass wir nicht mehr neben Ihnen wohnen.","en":"And despite 【our】 lovely new flat we are a little sad that we no longer live next to you.","rule":"Trotz + Genitiv: trotz unserer schönen neuen Wohnung. Wohnung is feminine, Genitiv feminine = der / unserer. Unser (masculine/neuter Nominativ) and unseres (Genitiv masculine/neuter) do not fit.","od":["our (Nominativ masculine/neuter). trotz needs the Genitiv, so this form does not fit.","our, Genitiv feminine. trotz + Genitiv, and die Wohnung is feminine: trotz unserer schönen Wohnung.","our, Genitiv masculine/neuter. Wohnung is feminine, so -es is wrong."]},{"x":"Nicole","no":5,"n":30,"a":"Freundliche","o":["Freundlich","Freundliche","Freundlichen"],"de":"【Freundliche】 Grüße aus Wallenhorst","en":"【Kind】 regards from Wallenhorst","rule":"Freundliche Grüße: no preposition, so Nominativ plural without article: the adjective ends in -e (freundliche Grüße). Compare mit freundlichen Grüßen (Dativ plural -en).","od":["friendly, no ending. It only works after sein or as a bare adjective.","friendly, Nominativ plural. No preposition, no article: freundliche Grüße (-e).","friendly, Dativ plural. It needs mit (mit freundlichen Grüßen)."]},{"x":"Andreas","no":6,"n":25,"a":"junge","o":["junge","jungen","junges"],"de":"Diese Seite ist für 【junge】 Leute gemacht, die gern mehr über gesunde Ernährung erfahren möchten.","en":"This site is made for 【young】 people who would like to learn more about healthy eating.","rule":"Für junge Leute: für + Akkusativ plural, no article before the adjective → ending -e (junge Leute). Jungen would follow an article (den jungen Leuten).","od":["young, ending -e. für + Akkusativ plural without article: junge Leute.","young, ending -en. This ending only comes after an article (die jungen Leute) or in the Dativ plural.","young, ending -es. This is neuter singular, and Leute is plural."]},{"x":"Annika","no":7,"n":23,"a":"schöne","o":["schöne","schönen","schönes"],"de":"Es warten auf Sie sehr 【schöne】 Gewinne im Wert von vielen Tausend Euro.","en":"Very 【beautiful】 prizes worth many thousands of euros are waiting for you.","rule":"Sehr schöne Gewinne: plural noun without article, adjective ending -e (Nominativ plural). Schönen would need an article (die schönen Gewinne).","od":["beautiful, ending -e. Plural noun without article: sehr schöne Gewinne.","beautiful, ending -en. It would need an article (die schönen Gewinne) or the Dativ plural.","beautiful, ending -es. It is neuter singular, but Gewinne is plural."]},{"x":"Annika","no":7,"n":25,"a":"unserem","o":["unsere","unserem","unseren"],"de":"Sie erhalten dieses Buch mit 【unserem】 Versprechen, es nach 10 Tagen zurückgeben zu können, sollte Ihnen das Buch nicht gefallen.","en":"You receive this book with 【our】 promise that you can return it after 10 days if you do not like it, without paying anything!","rule":"Mit + Dativ: mit UNSEREM Versprechen (das Versprechen is neuter, Dativ -em). Unsere / unseren do not match neuter Dativ.","od":["our, feminine or plural. It does not match the neuter Dativ after mit.","our, Dativ neuter. mit + Dativ: mit unserem Versprechen (das Versprechen is neuter).","our, Akkusativ masculine or Dativ plural. It does not match neuter Dativ singular."]},{"x":"Iris","no":8,"n":23,"a":"halbes","o":["halbe","halben","halbes"],"de":"Ich freue mich schon sehr darauf, denn schließlich haben wir uns fast ein 【halbes】 Jahr nicht gesehen.","en":"I am already very much looking forward to it, because after all we have not seen each other for almost 【half a】 year.","rule":"Ein HALBES Jahr: after ein (neuter Akkusativ) the adjective ending is -es: ein halbes Jahr. Halbe / halben do not match neuter.","od":["half, ending -e. It is for feminine or plural nouns; Jahr is neuter.","half, ending -en. It is for masculine Akkusativ or Dativ; Jahr is neuter.","half, ending -es. After ein + neuter Akkusativ the adjective ends in -es: ein halbes Jahr."]},{"x":"Sonja","no":9,"n":24,"a":"lange","o":["lange","langem","langer"],"de":"Ich hatte mich auf das Vorstellungsgespräch schon 【lange】 Zeit vorher vorbereitet.","en":"I had prepared for the interview 【a long】 time beforehand.","rule":"Schon LANGE Zeit vorher = a long time before. Lange Zeit is feminine Akkusativ without article, so the adjective ends in -e.","od":["long, ending -e. Zeit is feminine, Akkusativ without article: lange Zeit.","long, Dativ masculine/neuter. We need Akkusativ feminine.","long, Nominativ masculine or Dativ/Genitiv feminine. It is not Akkusativ."]},{"x":"Carolina","no":10,"n":22,"a":"dieses","o":["diese","diesen","dieses"],"de":"Ich kenne 【dieses】 Land jetzt schon recht gut.","en":"I now know 【this】 country quite well already.","rule":"Kennen takes the Akkusativ; Land is neuter: dieses Land. Diese = feminine / plural, diesen = masculine Akkusativ / Dativ plural.","od":["this, feminine/plural. Land is neuter.","this, Akkusativ masculine or Dativ plural. Land is neuter.","this, Akkusativ neuter. kennen + Akkusativ, and das Land is neuter: dieses Land."]},{"x":"Carolina","no":10,"n":28,"a":"unterschiede","o":["unterschied","unterschiede","unterschieden"],"de":"Zwischen der Schule hier und unserem Schulsystem in Australien gibt es einige 【Unterschiede】: In der Schweiz sprechen die Lehrer viel und die Schüler müssen Vieles im Kopf behalten oder aufschreiben.","en":"Between the school here and our school system in Australia there are some 【differences】: in Switzerland the teachers talk a lot and the pupils have to remember a lot or write it down.","rule":"Einige + plural noun: einige Unterschiede (capital letter in the exam: Unterschiede). Unterschied is the singular, unterschieden a participle.","od":["difference (singular), or past of unterscheiden. einige needs a plural noun.","differences (plural noun). einige + plural: einige Unterschiede.","distinguished (Partizip II). It is not a noun."]},{"x":"Vera","no":11,"n":23,"a":"meinem","o":["mein","meinem","meinen"],"de":"Als ich im Sommer 18 wurde, wollte ich mit 【meinem】 älteren Bruder zusammen eine kleine Wohnung mieten.","en":"When I turned 18 in the summer, I wanted to rent a small flat together with 【my】 older brother.","rule":"Mit + Dativ: mit MEINEM älteren Bruder (der Bruder is masculine, Dativ -em). Mein / meinen do not match the Dativ.","od":["my, Nominativ masculine/neuter. mit needs the Dativ.","my, Dativ masculine. mit + Dativ: mit meinem älteren Bruder.","my, Akkusativ masculine or Dativ plural. It does not match mit + Bruder."]},{"x":"Vera","no":11,"n":25,"a":"Freundinnen","o":["Freund","Freundin","Freundinnen"],"de":"Ich wohne jetzt mit drei 【Freundinnen】 zusammen in der Innenstadt.","en":"I now live in the city centre with three 【girlfriends】.","rule":"Mit drei FREUNDINNEN: mit + Dativ plural. The plural of Freundin is Freundinnen, the form is the same in the Dativ.","od":["friend (singular, male). drei needs a plural, and the flatmates are girls.","friend (singular, female). drei needs a plural.","friends (plural, female). mit drei Freundinnen: the plural of Freundin ends in -nen."]},{"x":"Vera","no":11,"n":28,"a":"wenig","o":["wenig","wenigen","weniger"],"de":"Ich staune selbst über meine Noten, wenn ich daran denke, wie 【wenig】 Zeit ich mir für Hausaufgaben nehme.","en":"I am surprised myself at my marks when I think about it and how 【little】 time I take for homework.","rule":"Wie WENIG Zeit = how little time. Wenig is the opposite of viel and does not change before an uncountable noun. Weniger = less (comparative), wenigen = with an article.","od":["little. wie wenig Zeit = how little time.","few, with an ending. It is for a plural noun or after an article.","less. wie weniger is not used."]},{"x":"Jennifer","no":12,"n":23,"a":"besondere","o":["besondere","besonderem","besonderen"],"de":"So kann man hier zum Beispiel 【besondere】 Fahrkarten kaufen, um mit dem Bus in einen anderen Ort zu fahren und mit dem Rad zurück.","en":"Here, for example, you can buy 【special】 tickets to take the bus to another place and cycle back.","rule":"Besondere Fahrkarten: plural noun without article → adjective ending -e in the Akkusativ plural. Besonderen / besonderem would need an article or preposition.","od":["special, ending -e. A plural noun without article in the Akkusativ: besondere Fahrkarten.","special, Dativ masculine/neuter (-em). kaufen + plural noun needs the Akkusativ.","special, ending -en. It would need an article (die besonderen Fahrkarten) or the Dativ plural."]},{"x":"Jennifer","no":12,"n":29,"a":"Einige","o":["Einige","Einigen","Einiges"],"de":"【Einige】 Ampeln schalten für Radfahrer sogar früher auf Grün als für Autos.","en":"【Some】 traffic lights even turn green earlier for cyclists than for cars.","rule":"EINIGE Ampeln = some traffic lights. Plural noun, so einige (-e); einiges is neuter singular (einiges Wasser), einigen would need a Dativ.","od":["some, Nominativ plural. einige Ampeln = some traffic lights.","some, Dativ plural. There is no Dativ verb or preposition.","some things, neuter singular. It cannot go with the plural Ampeln."]},{"x":"Rita","no":18,"n":26,"a":"beide","o":["beide","beiden","beides"],"de":"Sie sind 3 und 5 Jahre alt und 【beide】 sind sehr nett.","en":"They are 3 and 5 years old and 【both】 are very nice.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["both, Nominativ plural. beide is the subject of sind.","both, Dativ plural or after an article. Not the subject here.","both things, neuter singular. It refers to things, not people."]},{"x":"Rita","no":18,"n":27,"a":"ersten","o":["ersten","erster","erstes"],"de":"Wir haben in der 【ersten】 Woche bereits Vieles gemeinsam gemacht, sind in den Zoo und ins Kindermuseum gegangen.","en":"In the 【first】 week we have already done a lot together, we went to the zoo and to the children’s museum.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["first, ending -en. in der ersten Woche: in + Dativ feminine, after der the adjective ends in -en.","first, ending -er. It is used without a preceding article.","first, ending -es. It is neuter, but Woche is feminine."]},{"x":"Grenzacker","no":19,"n":25,"a":"unseres","o":["unser","unseren","unseres"],"de":"Ich möchte übrigens erst am Montag direkt zur Präsentation 【unseres】 Projekts in Wien zurück sein.","en":"By the way, I want to be back in Vienna only on Monday, directly for the presentation of 【our】 project.","rule":"Genitive neuter: das Projekt, des Projekts, so unseres Projekts. Unser = nominative, unseren = masculine accusative.","od":["our, Nominativ masculine (unser). The noun is Projekts, which is Genitiv, so this form does not fit.","our, Akkusativ masculine or Dativ plural (unseren). It does not fit a Genitiv neuter noun.","our, Genitiv neuter (unseres). das Projekt, des Projekts: zur Präsentation unseres Projekts."]},{"x":"Grenzacker","no":19,"n":26,"a":"dringenden","o":["dringende","dringenden","dringender"],"de":"In 【dringenden】 Fällen würde ich aber auch schon früher abreisen.","en":"In 【urgent】 cases I would leave earlier, though.","rule":"In + Dativ plural: in dringenden Fällen. The ending is -en after in … Fällen.","od":["urgent, Nominativ/Akkusativ plural (dringende). After \"in\" with Fällen the Dativ plural is needed, which ends in -en.","urgent, Dativ plural (dringenden). In dringenden Fällen: in + Dativ plural = -en.","urgent, Nominativ masculine or Genitiv/Dativ feminine (dringender). It does not fit the plural noun Fällen."]}]},{"key":"word","title":"Meaning words","rule":"No rule decides, the meaning of the sentence does: small words such as mehr, noch, schon, nur, einfach, unbedingt. Read the whole sentence.","items":[{"x":"Eva","no":2,"n":24,"a":"mehr","o":["mehr","noch","nur"],"de":"Sie erhalten daher die darauf folgende Ausgabe nicht 【mehr】.","en":"You will therefore not receive the following issue 【any more】.","rule":"Nicht mehr = no longer: Sie erhalten die Ausgabe nicht mehr. Nicht noch and nicht nur have a different meaning and do not fit.","od":["more. nicht mehr = no longer: you will no longer receive the issue.","still, yet. \"nicht noch\" is not a phrase; noch nicht = not yet has a different word order and meaning.","only. nicht nur = not only needs \"sondern auch\" and changes the meaning."]},{"x":"Annika","no":7,"n":24,"a":"einfach","o":["einfach","immer","noch"],"de":"Senden Sie uns 【einfach】 das beigefügte Antwortschreiben zurück und bestellen Sie damit – ohne Risiko – das Buch des Monats.","en":"【Simply】 send the enclosed reply form back to us and with it order – without risk – the book of the month.","rule":"Senden Sie uns EINFACH das Antwortschreiben = simply send. The adverb einfach softens the instruction. Immer / noch do not fit the meaning.","od":["simply. Senden Sie uns einfach … softens the instruction.","always. \"send us always\" does not fit one single request.","still, yet. It does not fit the request to send the form back."]},{"x":"Annika","no":7,"n":26,"a":"natürlich","o":["natürlich","schön","viele"],"de":"Behalten Sie das Buch, was wir 【natürlich】 hoffen, zahlen Sie nur 50 Prozent des sonst üblichen Preises in einer Buchhandlung.","en":"If you keep the book, which we 【of course】 hope, you pay only 50 per cent of the usual price in a bookshop.","rule":"Was wir NATÜRLICH hoffen = which we of course hope. Natürlich is an adverb of attitude; schön / viele do not fit.","od":["of course. An adverb of attitude: was wir natürlich hoffen.","nice. An adjective; it does not fit after \"was wir … hoffen\".","many. It needs a noun after it."]},{"x":"Annika","no":7,"n":29,"a":"unbedingt","o":["bald","bereits","unbedingt"],"de":"Antworten Sie 【unbedingt】 noch diese Woche!","en":"Reply 【without fail】 this very week!","rule":"Antworten Sie UNBEDINGT = without fail. It stresses the request. Bald / bereits do not fit (noch diese Woche follows).","od":["soon. noch diese Woche already gives the time, so bald does not add anything.","already. It does not fit a request about the future.","without fail. It stresses the request: Antworten Sie unbedingt."]},{"x":"Annika","no":7,"n":30,"a":"noch","o":["noch","schon","schnell"],"de":"Wenn Sie innerhalb der kommenden vier Wochen antworten, nehmen Sie immer 【noch】 an unserer Gewinnverteilung teil – vorausgesetzt, Sie haben die richtige Kundennummer.","en":"If you reply within the next four weeks, you always 【still】 take part in our prize distribution – provided you have the right customer number.","rule":"Immer NOCH = still: Sie nehmen immer noch teil. Noch with immer means 'continuing'. Schon would mean 'already', schnell = fast.","od":["still. immer noch = still: Sie nehmen immer noch teil.","already. immer schon = always, a different meaning.","fast. An adverb of manner; it does not fit with immer."]},{"x":"Iris","no":8,"n":26,"a":"mehr","o":["am meisten","ganz","mehr"],"de":"Und zu zwei macht es viel 【mehr】 Spaß!","en":"And with two of us it is much 【more】 fun!","rule":"Viel MEHR Spaß = much more fun: comparative. Am meisten is superlative, ganz does not fit.","od":["most (superlative). \"viel am meisten Spaß\" is not possible.","quite, whole. It does not combine with viel + Spaß.","more. viel mehr Spaß = much more fun (comparative)."]},{"x":"Iris","no":8,"n":27,"a":"noch","o":["auch","noch","nur"],"de":"Weißt du eigentlich, ob die Disko am Wittenberger Platz 【noch】 existiert?","en":"Do you actually know whether the disco on Wittenberger Platz 【still】 exists?","rule":"Ob die Disko NOCH existiert = whether it still exists. Noch means 'still'. Auch (also) and nur (only) do not fit the meaning.","od":["also. \"whether the disco also exists\" changes the meaning.","still. Ob die Disko noch existiert = whether it still exists.","only. It does not fit the question."]},{"x":"Carolina","no":10,"n":26,"a":"schon","o":["denn","ganz","schon"],"de":"Am Anfang hat mich das Sprachgemisch 【schon】 sehr verwirrt, aber jetzt verstehe ich fast alles, wenn jemand auf Schweizerdeutsch zu mir spricht.","en":"At the beginning the mixture of languages 【already】 confused me a lot, but now I understand almost everything when someone speaks Swiss German to me.","rule":"Am Anfang hat mich das SCHON sehr verwirrt = it did confuse me a lot. Schon stresses the statement before the contrast (aber jetzt). Denn / ganz do not fit.","od":["because. It is a connector that would send the verb to the end.","quite, whole. It does not fit with verwirrt.","indeed. Schon stresses the first statement before the contrast: it did confuse me a lot, but now …"]},{"x":"Carolina","no":10,"n":27,"a":"jetzt","o":["früher","jetzt","seit"],"de":"Am Anfang hat mich das Sprachgemisch schon sehr verwirrt, aber 【jetzt】 verstehe ich fast alles, wenn jemand auf Schweizerdeutsch zu mir spricht.","en":"At the beginning the mixture of languages already confused me a lot, but 【now】 I understand almost everything when someone speaks Swiss German to me.","rule":"Am Anfang … aber JETZT verstehe ich fast alles: jetzt contrasts with am Anfang (then vs now). Früher would be 'in the past', seit needs a period.","od":["earlier. It does not form the contrast with \"am Anfang\" that jetzt does.","now. Am Anfang … aber jetzt: then versus now.","since. It needs a point or a period (seit einem Jahr)."]},{"x":"Vera","no":11,"n":22,"a":"schon","o":["bloß","erst","schon"],"de":"Aber dann sind sie doch 【schon】 früher gefahren.","en":"But then they went 【earlier after all】.","rule":"Dann sind sie doch SCHON früher gefahren = after all they left earlier. Schon stresses 'earlier than planned'. Erst would mean 'only then'.","od":["merely. It does not fit \"sind früher gefahren\".","only (then). It would suggest later, not earlier.","already. Schon stresses that they left earlier than planned."]},{"x":"Thomas","no":14,"n":25,"a":"erst","o":["erst","jetzt","schon"],"de":"Wir mussten eine Nacht in Delhi verbringen und kamen so 【erst】 einen Tag später als geplant in Mumbai an.","en":"We had to spend a night in Delhi and so arrived in Mumbai 【only】 a day later than planned.","rule":"ERST einen Tag später = only a day later (not before). Erst expresses 'not earlier than'. Schon would stress 'already', jetzt = now.","od":["only (not until). erst einen Tag später = only a day later than planned.","now. It does not compare with the plan.","already. It has the opposite meaning (as early as)."]},{"x":"Rita","no":18,"n":23,"a":"nur","o":["doch","nur","schon"],"de":"Am Anfang war ich ziemlich enttäuscht, weil ich auf meine vielen Bewerbungsschreiben insgesamt 【nur】 zwei Antworten bekommen habe.","en":"At the beginning I was quite disappointed, because I had 【only】 received two answers to my many job applications.","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["but, yet (particle). It stresses or contradicts; it does not mean \"only\".","only. insgesamt nur zwei Antworten = only two answers in total.","already. It does not fit a disappointment about few answers."]},{"x":"Rita","no":18,"n":29,"a":"Besser","o":["Am besten","Besser","Gut"],"de":"【Besser】 kann man eine Stadt gar nicht kennen lernen, und es macht mir viel Spaß!","en":"【Better】 you cannot get to know a city, and I enjoy it a lot!","rule":"Word form. The options are forms of the same word: decide by the subject (person), the tense (past participle with haben / sein, infinitive with zu or after a modal) or the adjective ending (case, gender and article before it).","od":["the best way (superlative). It does not fit \"man kann gar nicht … kennen lernen\".","better (comparative). Better than this one cannot get to know a city.","well (positive). The comparison \"better\" is needed."]}]}]};
